(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["pt"] = {"ui":{"lead":"As pessoas não só jogaram os jogos: também os pintaram. Amplie 3300 anos de pinturas e figuras e veja os pormenores.","details":"Pormenores","links":"Ver ou jogar o jogo","record":"Sobre a obra","game":"Jogo","exhibit":"Acervo","room":"Sala","room_chance":"Acaso","hint":"Faça pinça ou use a roda para ampliar · arraste para mover · toque num número","r_artist":"Autor","r_date":"Data","r_place":"Local","r_medium":"Técnica","r_size":"Dimensões","r_museum":"Museu","r_credit":"Proveniência","r_rights":"Imagem","met":"The Metropolitan Museum of Art","cc0":"Acesso aberto (domínio público)","metlink":"A obra no site do museu","credit":"Imagens: The Metropolitan Museum of Art, The Cleveland Museum of Art, The Art Institute of Chicago e o Rijksmuseum, acesso aberto (domínio público).","cma":"The Cleveland Museum of Art","aic":"The Art Institute of Chicago","rijks":"Rijksmuseum, Amesterdão"},"nefertari":{"title":"A rainha Nefertari a jogar senet","artist":"Nina de Garis Davies (fac-símile)","date":"original c. 1290–1224 a.C. · fac-símile 1921–22","place":"Egito (Vale das Rainhas)","game":"Senet","medium":"Têmpera sobre papel (fac-símile a metade do tamanho)","p":["Nefertari foi a esposa principal de Ramsés II. Esta é a cópia de uma pintura do seu túmulo no Vale das Rainhas, feita dentro do túmulo em 1921–22; até as fendas e as falhas da parede foram copiadas.","Sentada diante de um tabuleiro, a rainha joga senet contra um adversário invisível. Pintado num túmulo, pensa-se que o jogo significava mais do que diversão: vencer a viagem para o além."],"spots":[["Dois tipos de peças","No tabuleiro há peças pontiagudas e peças em forma de carrinho de linha: uma para cada jogador."],["A mão da rainha","Os dedos preparam-se para pegar numa peça."],["Tabuleiro e suporte","O tabuleiro é visto de lado, por isso não se veem as casas. Assenta num suporte de pernas finas."],["O nome dela","O nome da rainha está escrito num oval, uma cartela."],["O adversário invisível","Ninguém está à frente dela: joga contra um adversário que não se vê."]]},"hydria":{"title":"Aquiles e Ájax a jogar um jogo de tabuleiro (hídria)","artist":"Atribuída ao Grupo de Leagros","date":"c. 510 a.C.","place":"Grécia (Ática)","game":"Um jogo de dados","medium":"Terracota (figuras negras)","p":["Durante o cerco de Troia, dois heróis gregos, Aquiles e Ájax, passam o tempo diante de um tabuleiro. A cena foi inventada por volta de 540 a.C. pelo oleiro e pintor Exéquias; o original conserva-se numa ânfora dos Museus do Vaticano.","O tema foi muito apreciado entre cerca de 540 e 480 a.C., e conhecem-se mais de 150 exemplos. Nesta hídria, a deusa Atena está no centro. Os heróis jogam um jogo em que as peças avançam conforme o lançamento dos dados."],"spots":[["Atena","A deusa Atena está de pé entre os dois."],["O herói da esquerda","Ainda de lança na mão, debruça-se sobre o tabuleiro."],["O herói da direita","Também não pousou as armas: um momento de jogo em plena guerra."],["O tabuleiro","O bloco baixo entre eles é o tabuleiro."],["O ombro","No ombro do vaso parte um carro."]]},"liubo":{"title":"Par de figuras sentadas a jogar liubo","date":"séc. I a.C. – séc. I d.C.","place":"China (dinastia Han)","game":"Liubo","medium":"Faiança com pigmento","p":["Dois jogadores de liubo, a grande moda da China Han. Figuras assim eram postas nos túmulos com o desejo de que os prazeres da vida continuassem depois da morte.","Na fotografia, entre eles estão o tabuleiro de liubo e as peças de osso do acervo deste museu. As figuras captam um momento dramático de uma partida acesa."],"spots":[["O tabuleiro de liubo","É o mesmo tabuleiro de «Tabuleiro e peças de liubo» do acervo: veja as marcas em T, L e V."],["O jogador da esquerda","Estuda o tabuleiro com calma."],["O jogador da direita","Mão no ar e boca bem aberta: terá acabado de fazer a jogada vencedora?"],["Peças no tabuleiro","As peças de osso estão nas duas pontas do tabuleiro."],["Peças fora do tabuleiro","Há mais peças no chão."]]},"shahnama":{"title":"«Buzurjmihr decifra o jogo indiano do xadrez», do Shahnama do xá Tahmasp","artist":"Pintura atribuída a ʿAbd al-Vahhab","date":"c. 1530–35","place":"Irão (Tabriz)","game":"Xadrez","medium":"Aguarela opaca, tinta, prata e ouro sobre papel","p":["Uma cena da epopeia de Ferdusi, o Shahnama (Livro dos Reis). O rei da Índia envia um emissário com um tabuleiro e peças de xadrez e desafia o rei persa Nushirvan: se descobrir como se joga, a Índia pagará tributo.","Só o jovem sábio Buzurjmihr o resolve a tempo. No Shahnama, a Pérsia envia depois o gamão em troca, e os indianos não o conseguem resolver. O rei e os cortesãos fitam o tabuleiro e os jogadores."],"spots":[["O tabuleiro","As peças estão num tabuleiro quadriculado, tão pequenas que mal se distinguem as formas."],["O rei Nushirvan","No trono, espera ver o enigma resolvido."],["À volta do tabuleiro","Os jogadores debruçam-se sobre o tabuleiro."],["Os versos","Os quadros de cima e de baixo trazem versos de Ferdusi."],["Os cortesãos","Homens de turbantes com altas varinhas vermelhas observam de pé."]]},"chaupar":{"title":"Shiva e Parvati a jogar chaupar, de uma série do Rasamanjari","artist":"Devidasa de Nurpur","date":"1694–95","place":"Índia (Basohli, Jammu)","game":"Chaupar (parente do antepassado do Ludo)","medium":"Aguarela opaca, tinta, prata e ouro sobre papel","p":["Uma página de uma série que ilustra o Rasamanjari, um poema amoroso sânscrito do século XV. O deus Shiva e a sua esposa Parvati estão sentados numa pele de tigre, à volta de um tabuleiro em forma de cruz.","Shiva acaba de lhe tirar um colar com batota, e Parvati suplica-lhe. Cor ousada, profundidade espacial ambígua, cor e gesto usados pelo seu significado: são as marcas da escola de Basohli."],"spots":[["O tabuleiro em cruz","O chaupar e o pachisi jogam-se num tabuleiro com esta forma de cruz."],["Barras brancas no tabuleiro","Provavelmente os dados compridos (pasa) do chaupar."],["Shiva","De corpo branco, com uma serpente ao pescoço."],["Parvati","De mão estendida, pede o colar de volta."],["A pele de tigre","Os dois estão sentados numa pele de tigre."]]},"shogi":{"title":"Uma jovem e um jovem a jogar shōgi («Chūnagon Kanesuke», dos Trinta e Seis Imortais da Poesia)","artist":"Suzuki Harunobu","date":"c. 1767–69","place":"Japão (Edo)","game":"Shogi","medium":"Xilogravura (nishiki-e)","p":["Uma estampa de uma série que alude aos Trinta e Seis Imortais da Poesia; esta representa o poeta Chūnagon Kanesuke. Numa noite de verão, junto a um mosquiteiro, uma jovem e um jovem jogam shogi.","Harunobu foi o artista que popularizou as estampas a cores, impressas com muitas pranchas. Até as peças do tabuleiro estão desenhadas com pormenor."],"spots":[["Um tabuleiro de shogi com pés","Um tabuleiro grosso com pés, como os de hoje."],["Uma caixinha","Provavelmente a caixa das peças."],["O mosquiteiro","Está pendurado um mosquiteiro verde: é uma noite de verão."],["A lanterna","Uma lamparina de pé ilumina o tabuleiro."],["O poema","O quadro em forma de nuvem traz o nome do poeta e um poema."]]},"sugoroku":{"title":"Duas jovens a jogar sugoroku","artist":"Utagawa Toyokuni I","date":"período Edo (finais do séc. XVIII – inícios do séc. XIX)","place":"Japão (Edo)","game":"Ban-sugoroku (parente do gamão)","medium":"Díptico de xilogravuras","p":["Duas estampas unidas numa imagem larga: jovens reunidas numa sala divertem-se com uma partida de ban-sugoroku. O jogo é parente do gamão, da mesma linha que o tabuleiro de sugoroku do Shōsōin deste acervo.","Há pedras brancas e pretas no tabuleiro, e a jovem da direita segura um copo para agitar os dados. Pela janela vê-se o monte Fuji."],"spots":[["O tabuleiro","Pedras brancas e pretas nas suas casas compridas."],["O copo dos dados","Agitam-se nele os dados."],["Pedras fora do tabuleiro","Já retiradas, ou ainda por entrar?"],["O monte Fuji","O Fuji para lá da janela."],["A junção","Aqui juntam-se as duas estampas."]]},"eakins":{"title":"Os jogadores de xadrez","artist":"Thomas Eakins","date":"1876","place":"Estados Unidos (Filadélfia)","game":"Xadrez","medium":"Óleo sobre madeira","p":["Na sala de uma casa de Filadélfia, dois amigos jogam xadrez enquanto o pai do artista, Benjamin Eakins, observa. Eakins aprendeu a cuidadosa construção do espaço e o pormenor rigoroso com o seu mestre em Paris, Gérôme.","Em 1881, Os jogadores de xadrez tornou-se a primeira obra que o Metropolitan aceitou como doação de um artista vivo."],"spots":[["As peças","Na sala escura, as peças do tabuleiro destacam-se na luz."],["O pai do artista","De pé, a ver a partida: Benjamin Eakins."],["O jogador da direita","O pintor George W. Holmes, amigo do pai do artista."],["A gaveta","Uma inscrição latina: «O filho de Benjamin Eakins pintou isto em 76.»"],["Sobre a lareira","Uma reprodução de um quadro de Gérôme, o mestre de Eakins."],["O gato","No chão, só o gato parece desinteressado da partida."]]},"weiqi":{"title":"Prato com imortais jogando weiqi","artist":"Autor desconhecido","date":"1425–36 (dinastia Ming, período Xuande)","place":"China","game":"Go (weiqi)","medium":"Laca entalhada vermelha e verde","size":"Alt. 3,5; larg. 14,9; compr. 23,5 cm","credit":"Doação de Florence e Herbert Irving, 2015","p":["Um prato de laca entalhada: dezenas de camadas foram aplicadas e depois entalhadas, com uma camada verde sob a vermelha, de modo que a profundidade do corte revela as cores. Dentro da borda lobulada, imortais jogam go sob um pinheiro.","Na China há a lenda de Lanke, o “cabo de machado apodrecido”: o lenhador Wang Zhi observou imortais jogando go na montanha e, ao voltar a si, havia passado tanto tempo que o cabo do machado apodrecera. Imortais diante do tabuleiro eram um tema querido. Quem é a figura em pé, os registros não dizem."],"spots":[["O tabuleiro","O tabuleiro de go entre os dois imortais, entalhado até nas linhas."],["Os imortais jogando","Duas figuras sentadas junto às pedras, em volta do tabuleiro."],["A figura em pé","Uma figura em pé, um pouco afastada. Lembra o lenhador da lenda, mas não se sabe quem é."],["A lua","Uma lua redonda no céu (ou talvez o sol)."],["O pinheiro","Um pinheiro de galhos abertos, árvore que costuma evocar longevidade e a terra dos imortais."],["A borda de peônias","Grandes peônias e folhas entalhadas ao redor da borda."]]},"webb":{"title":"Os jogadores de gamão (armário)","artist":"Philip Webb (projeto), Edward Burne-Jones (pintura), Morris, Marshall, Faulkner & Co. (fabricação)","date":"1861","place":"Grã-Bretanha (Londres)","game":"Gamão","medium":"Pinho pintado, óleo sobre couro, latão, cobre","size":"Alt. 185,4; larg. 114,3; prof. 53,3 cm","credit":"Rogers Fund, 1926","p":["Um dos primeiros móveis da firma que William Morris fundou com amigos em 1861. No couro das portas, um homem e uma mulher em trajes medievais jogam gamão, pintados a óleo. Foi exposto na Exposição Internacional de Londres de 1862.","Resume o objetivo do Arts and Crafts de apagar a fronteira entre belas-artes e artes aplicadas. O fundo de couro é puncionado com pontinhos, uma técnica medieval."],"spots":[["O tabuleiro","O tabuleiro de gamão na mesa, entre os dois."],["O homem","Um jovem, com uma peça na mão, estuda o tabuleiro."],["A mulher","À frente dele, uma mulher segura uma peça (ou um copo de dados)."],["Flores aos pés","Flores nascem aos pés dos jogadores."],["Couro puncionado","O fundo de couro é puncionado com pontos finos que pegam a luz."],["Faixas de losangos","Faixas de losangos sobre ouro emolduram as portas em cima e embaixo."]]},"liberale":{"title":"Os jogadores de xadrez","artist":"Liberale da Verona","date":"c. 1475","place":"Itália (Verona)","game":"Xadrez","medium":"Têmpera sobre madeira","size":"34,9 × 41,3 cm","credit":"Coleção Maitland F. Griggs, legado de Maitland F. Griggs, 1943","p":["Fragmento da frente de um cassone, o baú decorado que guardava o enxoval de uma noiva na Itália renascentista. Liberale também era conhecido por iluminar os livros de coro da catedral de Siena.","Mostra um momento de uma história de amor não identificada. No fragmento companheiro, uma donzela à janela parece chamar um jovem para entrar; aqui os dois jogam xadrez. Segundo o museu, ela está prestes a perder. O xadrez era uma imagem preferida do galanteio na literatura amorosa da época."],"spots":[["O tabuleiro","Um tabuleiro vermelho e branco com peças escuras; a partida parece perto do fim."],["O jovem","Estende a mão ao tabuleiro e parece prestes a vencer."],["A donzela","Sentada em frente; no painel companheiro, ela o chama de uma janela."],["A janela","Além da janela aberta, uma colina e o céu."],["Rapazes assistindo","Homens de braços cruzados acompanham a partida."],["Moças assistindo","Mulheres espiam a partida por trás da coluna."]]},"mirror":{"title":"Estojo de espelho com um casal jogando xadrez","artist":"Autor desconhecido","date":"1325-1350","place":"França (Paris)","game":"Xadrez","medium":"Marfim","size":"Diâmetro 10,2 cm","credit":"Compra com o Fundo J. H. Wade, 1940","p":["Este disco de marfim do tamanho da palma da mão cobria um espelho de mão. Na Paris do século XIV, um espelho de metal polido ficava entre duas placas de marfim e era levado consigo; marfins entalhados assim eram luxos apreciados pela corte e pela aristocracia.","Numa tenda com cortinas, um jovem e uma dama jogam xadrez. Nos romances medievais, o xadrez representava ao mesmo tempo o amor e a guerra. Já se sugeriu que o casal seja Tristão e Isolda, ou Lancelote e Guinevere, mas ninguém sabe. O museu pergunta aos visitantes: quem você acha que está ganhando?"],"spots":[["O tabuleiro","Um tabuleiro sobre uma mesa de um só pé, com algumas peças."],["O jovem","Estende a mão para fazer o próximo lance."],["A dama","Uma mulher de touca; as pontas dos dedos tocam uma peça."],["A mão fechada","A outra mão, fechada, repousa no colo. Estará segurando uma peça capturada?"],["A tenda","Cortinas presas dos dois lados, cenário comum do xadrez nos estojos de espelho."]]},"morris":{"title":"Um tabuleiro de jogo (trilha)","artist":"Peter Flötner","date":"1500-1546","place":"Alemanha","game":"Trilha (Nine Men’s Morris)","medium":"Xilogravura","credit":"Fundo Charles W. Harkness, 1923","p":["Uma xilogravura de Peter Flötner, um dos escultores mais talentosos da Nuremberg renascentista, que também desenhou ornamentos, móveis, modelos para ourives e um baralho famoso pela sátira. Sob a folhagem em espiral se esconde o tabuleiro da trilha («Mühle» em alemão): três quadrados um dentro do outro, ligados no meio de cada lado.","O tabuleiro tem 24 pontos. Quem alinha três peças suas (um moinho) tira uma do adversário. Gravuras assim também serviam de modelo aos artesãos, e o museu mostrou esta folha numa exposição de modelos e desenhos de ourives. Não se sabe se jogavam sobre o papel ou se o copiavam em madeira ou metal."],"spots":[["O quadrado central","O quadrado mais interno, coberto de entrelaçados finos."],["Um canto externo","Canto do quadrado externo: um dos 24 pontos onde ficam as peças."],["Um canto do meio","Os cantos do quadrado do meio também são pontos."],["As linhas de ligação","Faixas que ligam os três quadrados no meio de cada lado; as peças também andam por elas."],["Uma máscara","Cartelas em espiral com rostos em cima, embaixo e dos lados: ornamento grotesco renascentista."],["A borda de videira","Folhas e frutos talhados em branco sobre fundo preto."]]},"leifeng":{"title":"Jogo de tabuleiro do pagode Leifeng","artist":"Autor desconhecido","date":"1736-1795 (período Qianlong)","place":"China","game":"Jogo de corrida","medium":"Xilogravura; tinta sobre papel","size":"31 × 29,8 cm","credit":"Compra com o Fundo J. H. Wade, 2025","p":["Uma folha impressa feita para jogar, do reinado do imperador Qianlong da China Qing. Suas casas reúnem os personagens da Lenda da Serpente Branca: o espírito serpente Bai Suzhen («a Dama Branca»), sua companheira Xiaoqing («a Pequena Verde»), o jovem Xu Xuan (Xu Xian em versões posteriores) e o monge Fahai, que no fim aprisiona a Dama Branca sob o pagode Leifeng, à beira do Lago do Oeste.","O percurso gira em espiral desde uma casa marcada 起馬, «partida», até o pagode no centro. Provavelmente se corria pela história com dados, como no jogo do ganso ocidental; as regras não se conservaram. Segundo o museu, estampas coloridas assim eram vendidas nas cidades e penduradas nas paredes, parte da cultura visual urbana — cada cor impressa com sua própria matriz entalhada."],"spots":[["Partida","A casa marcada 起馬, «partida»: provavelmente o ponto de saída."],["A Dama Branca e a Pequena Verde","O espírito serpente Bai Suzhen e sua companheira Xiaoqing."],["Xu Xuan","O jovem que se casa com a Dama Branca."],["O monge Fahai","O monge que a aprisiona sob o pagode."],["O pagode Leifeng","O pagode do Lago do Oeste, em Hangzhou, onde a história termina."],["O centro","Uma mulher sentada diante do pagode e um homem ajoelhado: a última cena da história e, talvez, a chegada."]]},"tutinama":{"title":"O macaco ferido morde a mão do príncipe, seu parceiro de xadrez (de um Tuti-nama, Contos de um papagaio)","artist":"Dasavanta","date":"c. 1560","place":"Índia (corte mogol de Akbar)","game":"Xadrez","medium":"Têmpera, tinta e ouro sobre papel","size":"20 × 14,2 cm (pintura 10,2 × 10,6 cm)","credit":"Doação da Sra. A. Dean Perry, 1962","p":["Uma ilustração do Tuti-nama, os «Contos de um papagaio», feito na corte do imperador mogol Akbar. É uma das histórias que uma mãe papagaio conta aos filhotes para alertá-los contra amizades com outras espécies, como os filhotes de raposa. Nela, um macaco bom no xadrez jogava sempre com um príncipe.","Um dia, diante de convidados, o macaco fez uma piada grosseira e o príncipe lhe deu um tapa — e o macaco mordeu a mão do príncipe. Do lado de fora, à direita, criados preparam a comida enquanto os convidados olham espantados. Uma inscrição embaixo nomeia Dasavanta, que se tornaria um dos mestres mais célebres da corte mogol; jovem, ele pôs uma camada de azul frio sob a pintura."],"spots":[["O macaco","Morde a mão do príncipe, seu parceiro de xadrez."],["O príncipe","O príncipe mordido."],["O tabuleiro","Um tabuleiro de casas vermelhas no chão."],["Os convidados espantados","Os convidados da reunião."],["A comida","Do lado de fora, criados põem panelas no fogo."],["O texto persa","No alto, a história escrita em persa."]]},"teniers":{"title":"Partida de gamão","artist":"David Teniers","date":"década de 1640","place":"Flandres","game":"Gamão","medium":"Óleo sobre madeira, transposto para tela","size":"59 × 80,6 cm","credit":"Doação do Sr. e da Sra. Samuel D. Wise, 1943","p":["Uma partida de gamão de apostas altas, pintada pelo flamengo Teniers. O jogo é antiquíssimo: sua forma moderna surgiu no século XV, e o nome «backgammon» nasceu mais ou menos na época deste quadro. No século XVII era muito popular e jogado com frequência a dinheiro.","Curiosos cercam os dois jogadores, e junto à parede alguém marca os pontos. Pelas mulheres que observam — uma se debruça numa janela —, o museu entende que a sala é o salão de jogos de um bordel. Cenas de jogo assim muitas vezes traziam uma moral: o jogo a dinheiro era tolo, até perverso, e perda de tempo."],"spots":[["O tabuleiro","Um tabuleiro de gamão aberto sobre a mesa, a partida em andamento."],["O homem de branco","Um jogador de costas, estendendo a mão às pedras."],["O homem pensativo","O adversário, com a mão no rosto."],["O marcador","Um homem marca uma tábua na parede: os pontos ou as apostas?"],["A mulher à janela","Uma senhora que olha lá de cima."],["A sala dos fundos","Ao fundo, homens bebem ao lado de uma jovem."]]},"imari":{"title":"Prato com dois homens jogando go","artist":"Autor desconhecido","date":"século XVIII","place":"Japão (período Edo)","game":"Go","medium":"Porcelana moldada, esmaltes sobre o vidrado (Hizen, estilo Imari)","size":"2,4 × 13,8 cm","credit":"Coleção Severance e Greta Millikin, 1964","p":["Neste pequeno prato quadrado, dois homens jogam go sob um pinheiro: o de amarelo, sentado diante do tabuleiro posto no chão; o adversário de verde, encostado na árvore.","É porcelana de Imari feita em Hizen (hoje Saga e Nagasaki), e seus verdes lembram os esmaltes de Kutani. Foi feito para exportação, quando o Japão já substituíra a China como principal fornecedor de porcelana da Europa."],"spots":[["O tabuleiro de go","Um tabuleiro quadriculado, posto direto no chão."],["O homem de amarelo","Sentado diante do tabuleiro."],["O homem de verde","O adversário, encostado na árvore e sorrindo."],["O pinheiro","Um pinheiro estende os galhos por cima."],["A moldura vermelha","Uma moldura vermelha de cantos cortados envolve a cena."]]},"shoei":{"title":"As quatro artes (um de um par de biombos)","artist":"atribuído a Kanō Shōei","date":"fim do século XVI–início do XVII","place":"Japão (período Momoyama)","game":"Go","medium":"Um de um par de biombos de seis folhas; tinta e cor leve sobre papel","size":"153 × 358,6 cm","credit":"Fundo John L. Severance, 1979","p":["Um biombo de seis folhas atribuído a Kanō Shōei, da escola Kanō. Com seu par, mostra as «quatro artes» esperadas de um cavalheiro culto chinês: tocar o qin, jogar qi (go), caligrafia e pintura. Aqui, cavalheiros chineses de alta posição e seus criados descansam no campo, sob os pinheiros.","No centro, dois homens jogam go enquanto um terceiro observa. Perto, uma mesa guarda livros e um qin ainda no estojo de pano, à espera de ser tocado. A cena equilibra prazer e formalidade. O museu observa que um dos criados se distrai com o movimento de um peixe na água."],"spots":[["O tabuleiro de go","Um tabuleiro com pés; dois cavalheiros jogam frente a frente."],["Os cavalheiros","Dois jogadores e um terceiro que observa."],["A mesa","Provavelmente a mesa com os livros e o qin no estojo."],["Os criados","Criados que aguardam junto à mesa."],["O criado distraído","Deitado à beira da água, olha um peixe se mover."],["O pinheiro","Um grande pinheiro estende os galhos sobre a cena."]]},"umaya":{"title":"Biombo das cavalariças (go e shogi na varanda)","artist":"Autor desconhecido","date":"Início do século XVI","place":"Japão (período Muromachi)","game":"Go e shogi","medium":"Um de um par de biombos de seis folhas; tinta, cor e ouro sobre papel","size":"146,1 × 346,6 cm","credit":"Edward L. Whittemore Fund, 1934","p":["Este biombo de seis folhas unidas é um de um par. Os cavalos valiosos nas baias talvez sejam o tema principal, mas muita coisa acontece na varanda à frente.","Ali as pessoas desafiam-se em dois jogos diferentes: go à esquerda e shogi à direita. Segundo o museu, a animação vem do contraste entre os cavalos inquietos e a estratégia serena dos jogos. No Japão acreditava-se que os macacos protegiam os cavalos, e por vezes eram mantidos nas cavalariças."],"spots":[["O tabuleiro de go","Um tabuleiro de linhas finas com pedras pretas."],["Dois homens de barrete preto","Homens com alto eboshi preto: o de verde estende a mão ao tabuleiro, o de vermelho observa."],["O tabuleiro de shogi","Casas grandes, muito menos do que no tabuleiro de go."],["O adversário que ri","Um monge de cabeça rapada pega numa peça enquanto o homem em frente leva a mão à cabeça e ri às gargalhadas. Alguém acabou de marcar um ponto?"],["Um macaco","No fim da varanda, um macaco de casaco vermelho?"],["Um cavalo","Um cavalo preto empina-se, preso pelas cordas."]]},"goryeo":{"title":"Jarro de celadon com figuras a jogar go","artist":"Autor desconhecido","date":"Século XIII","place":"Coreia (dinastia Goryeo)","game":"Go (baduk)","medium":"Celadon com incrustações de engobe branco e preto","size":"Alt. 20,4 cm, diâm. 14,3 cm","credit":"Doação de John L. Severance, 1917","p":["Um jarro de celadon de Goryeo, com bico e asa. A incrustação — gravar linhas no barro, enchê-las de engobe branco e preto e depois vidrar e cozer — era a especialidade dos oleiros de Goryeo; aqui, dentro de uma moldura redonda, duas figuras sentadas sob um salgueiro destacam-se a branco.","Entre elas há um tabuleiro, e o museu compara a cena às imagens de partidas de go — baduk em coreano. Tocar cítara, jogar go, praticar caligrafia e pintura eram as «quatro artes» do letrado culto, e os seus encontros elegantes tornaram-se também motivos para artesãos. O celadon coreano com figuras humanas é raro."],"spots":[["O tabuleiro","O tabuleiro entre os dois, um quadrado branco."],["A figura à esquerda","Sentada de frente para o tabuleiro."],["A figura à direita","O adversário, sentado em frente."],["O salgueiro","Ramos de salgueiro pendem sobre eles, desenhados a engobe preto."],["A moldura de nuvens","Volutas como nuvens rodeiam a moldura redonda."],["O craquelado","Finas fissuras no vidrado. Formam-se ao arrefecer, porque o barro e o vidrado encolhem de forma diferente."]]},"kangra":{"title":"Casal a jogar chaupar num terraço","artist":"Autor desconhecido","date":"c. 1790–1800","place":"Índia (Pahari, escola de Kangra)","game":"Chaupar","medium":"Desenho com esboço prévio a ocre vermelho","size":"19,4 × 13,2 cm","credit":"Edward L. Whittemore Fund, 1936","p":["Desenho de um artista de Kangra, nas colinas pahari ao pé dos Himalaias. O primeiro esboço foi feito a vermelho (ocre vermelho) e depois afinado a preto. Sem cor por cima, pode seguir-se cada linha das figuras e dos objetos.","Um homem e uma mulher, sentados num terraço de cada lado de um tabuleiro em cruz, jogam chaupar, antigo jogo de corrida indiano na mesma cruz do pachisi, em que se avança lançando dados compridos (pasa). As casas ainda não estão desenhadas no tabuleiro. Criadas servem o casal."],"spots":[["O tabuleiro em cruz","Um tabuleiro em forma de cruz, no chão. As casas ainda não foram desenhadas."],["A mulher","Com a palma para cima: prestes a lançar os dados?"],["O homem","Turbante com penacho; estende a mão para o tabuleiro."],["A criada à esquerda","Segura um pequeno frasco e estende um pano."],["A criada à direita","Segura um utensílio de cabo comprido e um pequeno recipiente."],["O esboço vermelho","À volta do turbante, o esboço vermelho aparece sob as linhas pretas."]]},"vuillard":{"title":"A partida de damas (de Paisagens e interiores)","artist":"Édouard Vuillard","date":"1899","place":"França","game":"Damas","medium":"Litografia a cores (estado III/III); impressa por Auguste Clot, editada por Ambroise Vollard","size":"Imagem 33 × 25,7 cm (folha 38 × 30,8 cm)","credit":"Doação do Hanna Fund, 1951","p":["Ambroise Vollard, comerciante de pintura impressionista, foi também um importante editor de gravuras. Em 1895 encomendou a Pierre Bonnard um álbum de 12 litografias a cores e depois publicou muitos outros, entre eles Paisagens e interiores, de Vuillard, impresso pelo mestre impressor Auguste Clot.","Bonnard e Vuillard pertenciam aos nabis — «profetas» em hebraico —, que procuravam uma arte nova em que a forma e a cor exprimissem por si o sentimento, e que gostavam de cenas da vida urbana e familiar. Numa sala cheia de padrões, dois homens enfrentam-se diante de um tabuleiro de damas enquanto uma mulher, de pé, observa. Em francês o jogo chama-se «dames»; a nota a lápis no canto inferior esquerdo diz «partie de dames», uma partida de damas."],"spots":[["O tabuleiro","Um pequeno tabuleiro xadrezado, com as peças dispostas."],["O homem à esquerda","Um homem de barba estende a mão sobre o tabuleiro."],["O homem à direita","O adversário, debruçado sobre o tabuleiro numa poltrona, meio escondido pela mulher de pé."],["A mulher de pé","Com a mão no queixo, acompanha a partida."],["O candeeiro","Um candeeiro junto à parede. Papel de parede e estofos estão cheios de padrões."],["A nota a lápis","No canto inferior esquerdo, a lápis: «partie de dames», uma partida de damas."]]},"talbot":{"title":"Os jogadores de xadrez (fotografia antiga)","artist":"Atribuída a William Henry Fox Talbot","date":"c. 1843–47","place":"Inglaterra","game":"Xadrez","medium":"Prova em papel salgado","size":"19,9 × 15 cm","credit":"Adquirida com fundos do Sr. e da Sra. Everett Kovler","p":["O processo negativo-positivo inventado por Talbot, com as cópias ilimitadas que tornou possíveis, dominou a fotografia até à era digital. As suas primeiras experiências mostram tanto o interesse científico como a ambição artística, e os estudiosos confirmaram que fez dez ou mais vistas de jogadores de xadrez.","Mas esta talvez não seja sua: esta prova e outras da mesma cena não estão assinadas e usam papel diferente do habitual de Talbot. Os retratados seriam o fotógrafo Antoine Claudet e o assistente de Talbot, Nicolaas Henneman; estudos recentes sugerem que as imagens foram feitas no estúdio de Claudet, passaram para Henneman e chegaram a Talbot como parte do pagamento de uma dívida (nota do museu)."],"spots":[["O tabuleiro","O tabuleiro sobre a mesa, com as peças alinhadas."],["O homem de cartola","Sem tirar o chapéu, pega numa peça."],["O pensativo","De mão no queixo, o adversário estuda o tabuleiro."],["A cortina","Uma cortina ao fundo — um cenário para a fotografia?"],["Outro chapéu","Outra cartola repousa no suporte à direita."]]},"pvl":{"title":"Homens a jogar aos dados","artist":"Mestre PVL","date":"c. 1520","place":"Países Baixos","game":"Dados","medium":"Gravura a buril sobre papel","size":"9,4 × 9,4 cm (circular)","credit":"Coleção Charles Hack e Hearn Family Trust, adquirida em 2023","p":["Obra de um gravador anónimo ativo nos Países Baixos no início do século XVI, chamado Mestre PVL pelo monograma «PVL» gravado em baixo à esquerda. Numa gravura redonda que cabe na palma da mão, linhas finíssimas e cerradas constroem a profundidade da sala e a textura das roupas.","Sobre a mesa há dois dados. Um homem inclinado e um jovem de gola de pele apontam e discutem, talvez sobre a contagem. Atrás, mulheres observam, e debaixo da mesa há um jarro de vinho. Os dados estão ligados às apostas desde a Antiguidade e foram proibidos vezes sem conta."],"spots":[["Os dados","Dois dados a rolar sobre a mesa."],["As mãos que apontam","Dois dedos encontram-se sobre a mesa — uma disputa pela contagem?"],["O homem de chapéu largo","Inclinado; as mangas golpeadas e tufadas eram moda na época."],["O jovem de gola de pele","Um jovem de grande chapéu e gola de pele."],["As mulheres que observam","Mulheres espreitam o jogo por trás."],["O monograma","«PVL» em baixo à esquerda — a única pista do nome do artista."]]},"kiyohiro":{"title":"Jogadoras de sugoroku","artist":"Torii Kiyohiro","date":"c. 1750","place":"Japão (período Edo)","game":"Ban-sugoroku","medium":"Xilogravura a cores (benizuri-e), ōban; editor Urokogataya","size":"43,5 × 29,3 cm","credit":"Coleção Clarence Buckingham","p":["Torii Kiyohiro foi um artista de ukiyo-e ativo de cerca de 1737 a 1776. Esta é uma benizuri-e, impressa com poucas matrizes de cor — rosa beni, verde e afins — nos anos anteriores ao aparecimento, em 1765, das nishiki-e a cores plenas.","O jogo no suporte negro é o ban-sugoroku: dois jogadores lançam os dados e movem peças brancas e pretas, e ganha quem tirar primeiro todas as suas. É da mesma família do gamão, e as gravuras ukiyo-e mostram muitas vezes mulheres a jogá-lo. Atrás, uma mulher fuma um cachimbo comprido e observa."],"spots":[["O tabuleiro","Um tabuleiro de sugoroku sobre o suporte, com peças brancas e pretas."],["A figura à esquerda","Estende a mão para mover uma peça."],["A mulher à direita","Inclinada sobre o tabuleiro, a adversária estuda as peças."],["A mulher do cachimbo","Com um longo cachimbo kiseru, acompanha a partida por trás."],["A mão erguida","A mulher à direita ergue algo pequeno e negro — o copo dos dados?"],["A assinatura","«Torii Kiyohiro hitsu», com o selo do editor Urokogataya."]]},"ingram":{"title":"O jogo do xadrez chinês","artist":"John Ingram, segundo François Boucher","date":"1741–63","place":"França (Paris)","game":"Xiangqi","medium":"Água-forte e buril","size":"Folha 39,4 × 27,7 cm (chapa 24,5 × 16,4 cm)","credit":"Coleção Elisha Whittelsey, 1966","p":["Um desenho do pintor francês François Boucher gravado pelo londrino John Ingram. Ingram mudou-se para Paris e, entre 1741 e 1763, fez uma série de gravuras segundo as chinoiseries de Boucher — a China imaginada pelos europeus. O título diz «LE JEU D'ECHETS CHINOIS», o jogo do xadrez chinês.","Uma mulher de penteado alto move uma peça no tabuleiro que tem no colo, enquanto uma criança pequena observa. O jogo é tido como xiangqi, mas as peças reais de xiangqi são todas discos planos, e aqui há peças altas ao lado de pequenas peças quadradas. A palmeira e a figura sentada na urna pertencem menos à China do que ao país distante com que a Europa de então sonhava."],"spots":[["Tabuleiro e peças","O tabuleiro no colo, com peças altas e quadradas. As peças reais de xiangqi são discos planos."],["A mão na peça","A mão direita move uma peça."],["A face apoiada","Com a mão esquerda no queixo, olha para o tabuleiro."],["A criança que observa","Uma criança de pé junto ao tabuleiro acompanha o jogo."],["A figura na urna","Uma figura sentada de pernas cruzadas sobre uma grande urna."],["Título e nomes","«Dessiné par Fr. Boucher», «Gravé par Ingram» e o título «LE JEU D'ECHETS CHINOIS»."]]},"posada":{"title":"Jogo da Glória (Jogo do Ganso)","artist":"José Guadalupe Posada","date":"1909","place":"México","game":"Jogo do ganso","medium":"Gravura em relevo sobre zinco, em papel","size":"29,3 × 39,4 cm","credit":"William McCallin McKee Memorial Endowment","p":["Uma folha para jogar, feita pelo gravador mexicano Posada — famoso pelas suas calaveras, as caveiras — para o editor da Cidade do México Antonio Vanegas Arroyo. A faixa em baixo à esquerda diz «JUEGO DE LA OCA» (jogo do ganso), e o percurso enrola-se da casa 1 até à 63, no centro.","As regras (EXPLICACION) estão impressas no meio: um primeiro lançamento de 5 e 4 leva ao 26, de 6 e 3 ao 53. Quem cai num ganso (uma ave) volta a contar o mesmo; na estalagem (Venta, 19) espera-se duas vezes; no poço (Poso, 31) e na prisão (Carcel, 52) fica-se até que outro chegue; o labirinto (42) manda voltar ao 39 e a morte (Muerte, 58) ao início. É preciso cair exatamente no 63. Também se pagavam apostas em certas casas: era um jogo de apostas."],"spots":[["As regras","A «EXPLICACION» do centro: o que faz cada casa e quando se paga a aposta."],["A casa 1","A partida. Daqui o percurso enrola-se para o centro."],["O poço (31)","Um poço como uma fonte. Quem cai fica até chegar outro."],["A morte (58)","A casa da caveira: volta-se ao início."],["A faixa do título","«JUEGO DE LA OCA» na faixa em baixo à esquerda, com crianças a brincar por baixo."],["O nome do editor","A faixa da deusa diz «IMPRENTA DE A. VANEGAS ARROYO», a casa que publicou muitas gravuras de Posada."]]},"jintile":{"title":"Placa com mulheres a jogar um jogo de tabuleiro","artist":"Autor desconhecido","date":"Século XIII","place":"China (dinastia Jin)","game":"Jogo de tabuleiro (provavelmente go)","medium":"Terracota (relevo moldado)","size":"Alt. 27,3 cm, larg. 24,8 cm, prof. 5,4 cm","credit":"Compra, donativos dos Friends of Asian Art, 2002","p":["Uma placa em relevo feita sob os Jin (1115–1234), a dinastia do povo jurchen que governou o norte da China. Sob uma árvore em flor, duas mulheres sentam-se frente a frente num estrado, com um tabuleiro entre elas.","O tabuleiro tem uma quadrícula fina, por isso provavelmente jogam go. A da direita inclina-se e aponta para o tabuleiro enquanto a da esquerda observa. Muitos túmulos da época Jin no norte da China eram revestidos com tijolos em relevo com cenas do quotidiano, e esta placa provavelmente decorava um deles."],"spots":[["O tabuleiro","Um tabuleiro de quadrícula fina, provavelmente de go."],["A mão que aponta","A mulher da direita aponta para o tabuleiro. A próxima jogada?"],["A mulher da esquerda","De cabelo apanhado no alto, olha para o tabuleiro."],["A mulher da direita","Inclinada sobre o tabuleiro."],["A árvore em flor","Ramos de uma árvore em flor estendem-se sobre elas."],["O estrado","O estrado onde se sentam, com um saial ondulado entre os pés."]]},"kyosai":{"title":"Um pum estraga uma partida de go (de um álbum de esboços)","artist":"Kawanabe Kyōsai","date":"Meados a finais do século XIX","place":"Japão (períodos Edo a Meiji)","game":"Go","medium":"Uma dupla página de um álbum em acordeão de 26 folhas duplas; tinta e cor sobre papel","size":"Álbum (fechado) 28 × 18 cm","credit":"Doação de Anne e Anthony d’Offay em honra de Evan Turner","p":["Uma cena de um álbum de esboços de Kawanabe Kyōsai (1831–1889), pintor ativo do fim do xogunato à era Meiji, desenhada com traços rápidos e livres nas páginas de um álbum em acordeão. Formado na técnica exigente da escola Kanō, Kyōsai era também adorado pelos seus demónios, caricaturas e sátiras.","O título do museu diz tudo: «Um pum estraga uma partida de go». À esquerda, um homem de barrete preto dobra-se; à direita, o tabuleiro voa, as taças despejam uma chuva de pedras e o adversário cai de costas. Uma partida séria arruinada de um só golpe: Kyōsai regista com o seu pincel veloz o velho humor japonês do pum, já presente em rolos medievais."],"spots":[["O homem de barrete preto","Dobrado, com o traseiro de fora — o causador da confusão?"],["O tabuleiro a voar","O tabuleiro quadriculado sai disparado na diagonal."],["Taças e pedras","Duas taças viram-se e as pedras caem como chuva."],["O leque","Um leque aberto voa junto ao tabuleiro."],["O adversário derrubado","Caído de costas, de olhos arregalados."],["O traço","Linhas de tinta enérgicas, como feitas de uma vez sem esboço."]]},"yokuts":{"title":"Tabuleiro de jogos de azar","artist":"Tecelã yokuts (nome desconhecido)","date":"c. 1900","place":"Estados Unidos (perto de Dunlap, Califórnia)","game":"Huuchuish (dados de casca de noz)","medium":"Fibras vegetais (cestaria em espiral)","size":"Alt. 5,1 cm, diâm. 61 cm","credit":"Adquirido com fundos da Sra. Leonard S. Florsheim Jr.","p":["Muitos povos indígenas da Califórnia praticavam jogos de azar. Este tabuleiro servia para o huuchuish, um jogo de dados só de mulheres: lançavam-se oito dados de casca de noz sobre o tabuleiro e contava-se com pauzinhos.","O desenho circular tecido no tabuleiro mostra o próprio jogo — os dados, os pauzinhos de contagem e as jogadoras (nota do museu). É um utensílio de jogo que traz a imagem do seu próprio jogo. Na fotografia, há dados de casca de noz sobre o tabuleiro e à volta."],"spots":[["As jogadoras","Figuras à volta da borda: quem participa no jogo."],["Pauzinhos de contagem","Feixes de tracinhos verticais: os pauzinhos para contar."],["Motivos redondos","Pequenos motivos redondos — os dados, talvez?"],["Um dado de noz","Um dado de casca de noz. Lançavam-se oito no tabuleiro."],["A faixa de triângulos","Uma faixa de triângulos escuros dá a volta toda."],["O centro","A espiral do entrançado sai do meio, rodeada por um círculo tracejado."]]},"hokkei":{"title":"Ushiwakamaru vence Benkei no sugoroku","artist":"Totoya Hokkei","date":"c. 1825","place":"Japão (período Edo)","game":"Ban-sugoroku","medium":"Surimono (xilogravura a cores, shikishiban)","size":"21,8 × 19,1 cm","credit":"Doação de Helen C. Gunsaulus","p":["Um surimono de Totoya Hokkei (1780–1850), discípulo de Hokusai. Os surimono eram gravuras de encomenda privada — muitas vezes de círculos de poesia, com os seus próprios versos — e acabadas com mais luxo do que o ukiyo-e comercial, com bom papel e pigmentos metálicos.","Ushiwakamaru, nome de infância do herói Minamoto no Yoshitsune, e o gigantesco monge guerreiro Benkei. O seu famoso encontro foi um duelo na ponte Gojō de Quioto, mas aqui o combate torna-se uma partida de sugoroku: o rapaz senta-se tranquilo atrás do tabuleiro e Benkei, de alabarda às costas, coça a cabeça derrotado. Parece uma recriação brincalhona."],"spots":[["O tabuleiro de sugoroku","Um tabuleiro em forma de caixa com peças brancas e pretas."],["Benkei a coçar a cabeça","De armadura completa, o vencido coça a cabeça."],["Ushiwakamaru","O jovem herói, sentado atrás do tabuleiro."],["A alabarda","A lâmina da grande naginata de Benkei."],["O poema","Versos em cima à direita, provavelmente do círculo que encomendou a gravura."],["A assinatura","A assinatura de Hokkei na cartela em baixo à direita."]]},"vorsterman":{"title":"Jogadores de gamão (cena noturna)","artist":"Lucas Emil Vorsterman, segundo Adam de Coster","date":"c. 1630","place":"Flandres (Antuérpia)","game":"Gamão","medium":"Gravura a buril sobre papel marfim","size":"Imagem 25,5 × 34,4 cm","credit":"Coleção Bernard F. Rogers","p":["Adam de Coster foi um destacado pintor de cenas noturnas à luz de velas na Antuérpia de cerca de 1630, quando Vorsterman, na mesma cidade, gravava obras de contemporâneos populares. Discípulo de Rubens, Vorsterman zangou-se com o mestre e partiu para Inglaterra, passando depois a fazer gravuras mais contrastadas, estilizadas e caravaggescas como esta.","Em volta de uma mesa numa sala escura, homens reúnem-se diante de um tabuleiro de gamão. Seguindo o tratamento da luz de De Coster, duas chamas de vela iluminam os rostos à volta da mesa (nota do museu). À direita, um jovem tocador de alaúde olha para nós."],"spots":[["O tabuleiro","Um tabuleiro de gamão aberto como uma caixa sobre a mesa."],["A vela","Uma vela no castiçal: a chama ilumina os rostos."],["O homem do cachimbo","De chapéu largo, fuma e observa o jogo."],["O homem de costas","Inclinado, com as mãos na mesa."],["O tocador de alaúde","Um jovem com um alaúde, a sorrir para nós."],["Os nomes","«A. De Coster pi.» em baixo à esquerda, «Vorsterman» em baixo à direita."]]},"zorn":{"title":"Jogadores de xadrez","artist":"Anders Zorn","date":"1891","place":"Suécia","game":"Xadrez","medium":"Água-forte sobre papel vergé marfim","size":"Imagem 13,5 × 9,6 cm (chapa 13,9 × 10 cm)","credit":"Coleções de águas-fortes de Anders Zorn de Wallace L. DeWolf e Charles Deering","p":["Uma água-forte do artista sueco Anders Zorn (1860–1920), famoso internacionalmente pelos retratos a óleo e aguarela, que deixou também uma vasta obra gravada. A chapa não é maior do que uma mão.","Bastam linhas rápidas e oblíquas sobrepostas para que surjam do cobre uma sala escura e duas pessoas. O homem à frente, de costas, inclina-se sobre o tabuleiro; a figura em frente baixa os olhos, a pensar na próxima jogada. As peças estão desenhadas com traços finos. Não se sabe quem posou."],"spots":[["Tabuleiro e peças","A zona clara em baixo é o tabuleiro; os traços curtos verticais são as peças."],["O homem à frente","De costas, inclinado sobre o tabuleiro."],["O adversário","De cabeça baixa, olha o tabuleiro."],["O fundo escuro","O fundo da sala, feito de linhas verticais."],["Linhas oblíquas","O casaco é feito de traços diagonais rápidos sobrepostos."],["A assinatura","Assinado «Zorn» a lápis sob a chapa."]]},"harunobu-sugoroku":{"title":"A ver a partida (sugoroku)","artist":"Suzuki Harunobu","date":"c. 1766","place":"Japão (período Edo)","game":"Ban-sugoroku","medium":"Xilogravura a cores (chūban, surimono)","size":"28,5 × 21 cm","credit":"Coleção Clarence Buckingham","p":["Suzuki Harunobu (1725?–1770) foi a figura central quando, por volta de 1765, nasceram as nishiki-e, gravuras a cores plenas impressas com muitas matrizes. Esta é um surimono de edição privada, e as suas cores suaves e sobrepostas mostram a novidade.","Numa sala com ameixeiras em flor, duas raparigas jogam num tabuleiro de sugoroku em forma de caixa, enquanto uma terceira, de pé, observa. Peças brancas e pretas enchem o tabuleiro; a da esquerda move uma e a da direita estende a mão. A porta de correr ao fundo tem pintadas uma cascata e pinheiros."],"spots":[["O tabuleiro de sugoroku","Um tabuleiro de ban-sugoroku em forma de caixa, com peças brancas e pretas."],["A rapariga da esquerda","De quimono com grous de papel, move uma peça."],["A rapariga da direita","Inclinada, estende a mão para o tabuleiro."],["A espectadora","De pé, observa a partida com um objeto de cabo comprido na mão."],["A ameixeira","Uma ameixeira branca estende os ramos lá de cima."],["A porta pintada","Uma porta de correr pintada com uma cascata e pinheiros."]]},"kota":{"title":"Maharao Kishor Singh II de Kota adorando Krishna como Brij Rajji","artist":"Autor desconhecido","date":"c. 1825","place":"Índia (Rajastão, Kota)","game":"Pachisi","medium":"Têmpera de goma, prata e ouro sobre papel","size":"24,5 × 18,8 cm","credit":"James Albert and Mary Gardiner Ford Memorial Fund","p":["O soberano do pequeno estado principesco de Kota (r. 1819–28), vestido de sacerdote da seita Pushti Marg, oferece uma lamparina de cinco chamas. No pequeno santuário do altar estão imagens de metal de Krishna ladeado por duas consortes — um ícone adorado apenas em Kota.","Do teto pendem muitas lâmpadas de vidro, e nos degraus que sobem ao altar estão brinquedos e jogos para divertir Krishna e os seus companheiros: elefantes de latão, vacas de prata, bolas e um tabuleiro de pachisi (nota do museu). O pano vermelho em cruz é esse tabuleiro — o pachisi oferecido como brinquedo do deus."],"spots":[["O tabuleiro de pachisi","O pano vermelho em cruz nos degraus: um tabuleiro de pachisi."],["Elefantes","Dois elefantes de latão junto ao tabuleiro."],["Bolas","Bolas douradas no degrau de cima."],["Krishna","As imagens de Krishna e de duas consortes no santuário."],["O soberano e a lamparina","Vestido de sacerdote, oferece uma lamparina de cinco chamas."],["Lâmpadas de vidro","Uma multidão de lâmpadas pende do teto."]]},"coyote":{"title":"Jogo do Coiote","artist":"Seguidor de José Guadalupe Posada","date":"Sem data","place":"México","game":"Coiote e galinhas (da família da raposa e dos gansos)","medium":"Gravura em relevo sobre zinco, em papel","size":"38,2 × 30,5 cm","credit":"William McCallin McKee Memorial Endowment","p":["Uma folha para jogar, impressa em relevo sobre zinco como as que Posada fazia para as tipografias populares da Cidade do México. Em cima lê-se «JUEGO DEL COYOTE» (jogo do coiote); à volta, coiotes assaltam o galinheiro e um homem brande um pau para afugentar um. A faixa de baixo diz «Propriedade de Ildefonso T. Orellana».","As regras estão impressas na «EXPLICACION» em baixo: dois jogadores, um com quinze galinhas e outro com um só coiote. As galinhas avançam ou andam para os lados, mas nunca recuam; o coiote move-se em todas as direções e come uma galinha saltando por cima dela se atrás houver lugar vazio. As galinhas ganham se encurralarem o coiote. É o mesmo jogo de caça que o europeu da raposa e dos gansos."],"spots":[["O lugar do coiote","A cabeça do coiote no círculo central: aí começa o coiote."],["Os lugares das galinhas","Círculos com galinhas: aí se põem as suas peças."],["As regras","A «EXPLICACION»: peças, movimentos e como ganhar."],["O título","«JUEGO DEL COYOTE» — jogo do coiote."],["Um coiote atrás de uma galinha","Em baixo à esquerda, um coiote vai a uma galinha."],["O homem do pau","Em cima à direita, um homem ergue um pau contra um coiote."]]},"mons":{"title":"Gamão por Mons (Bergen), 1709","artist":"Pieter Nolpe (chapa e editor)","date":"Chapa 1623–53; impressão c. 1709","place":"Países Baixos (Amesterdão)","game":"Trictrac (da família do gamão)","medium":"Água-forte, buril e verso tipográfico","size":"Folha 35,8 × 18,6 cm (chapa 12,9 × 17,5 cm)","credit":"","p":["Quatro homens jogam trictrac a uma mesa. Segundo o registo do museu, as letras A–D indicam o duque de Marlborough, o eleitor da Baviera, o senhor de Ouwerkerk e o duque de Villeroy. É uma sátira ao cerco e à tomada de Mons (Bergen em neerlandês) aos franceses pelos aliados em 1709, apresentada como uma partida em que se joga a cidade. No quarto do fundo (E), o rei Filipe V de Espanha está com uma mulher.","A chapa está assinada por Pieter Nolpe como autor e editor, mas Nolpe morreu no início da década de 1650; provavelmente reimprimiu-se uma velha chapa do século XVII, acrescentando letras e um verso novo. O poema começa dizendo que o jogo dos grandes senhores é só tiktak e verkeer (dois jogos de tabuleiro da família do gamão) e depois troça de cada jogador."],"spots":[["O tabuleiro","O trictrac na mesa: joga-se uma cidade."],["A, Marlborough","De pé, olha o tabuleiro: o general inglês dos aliados."],["B, o eleitor da Baviera","Sem chapéu, afundado na cadeira."],["C, Ouwerkerk","De chapéu com plumas: o general neerlandês."],["E, o quarto do fundo","Ao fundo, Filipe V com uma mulher no quarto."],["O verso","Verso neerlandês impresso em baixo, a troçar dos jogadores A a E."]]},"stembus":{"title":"A urna: um jogo do ganso político","artist":"Johan Michaël Schmidt Crans (gravador)","date":"1867","place":"Países Baixos","game":"Jogo do ganso (sátira)","medium":"Litografia","size":"66 × 50 cm","credit":"","p":["Uma gravura satírica em forma de jogo do ganso, publicada com o semanário De Nederlandsche Spectator, n.º 9, de 2 de março de 1867, com uma folha solta de regras (registo do museu). As casas trazem retratos dos ministros da época.","Começa-se no Binnenhof, o parlamento da Haia, e termina-se no centro, na casa 64, «Insulinde» — nome poético das Índias Orientais Neerlandesas —, onde um retrato do ministro Pieter Mijer pende da ilha de Java. Mijer passara de ministro das Colónias a governador-geral das Índias, e a nomeação provocou uma tempestade política. A casa a mais, uma além das 63 habituais, está lá provavelmente pela piada final."],"spots":[["A partida","O edifício em cima à esquerda: começa-se no Binnenhof da Haia."],["O retrato de Mijer","Casa 63: um retrato emoldurado de Pieter Mijer, pendurado da ilha por cordas."],["Insulinde 64","A ilha e o número 64 no centro: a chegada."],["A urna","«DE STEMBUS» (a urna) em baixo à direita: a caixa do título."],["Os ministros","Os rostos dos ministros da época espreitam das casas."],["O galo","Um galo numa casa; não se sabe de que troça."]]},"koorai":{"title":"Coreanos em volta de um jogo de tabuleiro (do Nippon de Siebold)","artist":"James Erxleben (litógrafo), segundo um desenho de «Toioske»","date":"1832–52","place":"Países Baixos (Leiden) / coreanos","game":"Jogo de tabuleiro (provavelmente go)","medium":"Litografia tonal, colorida à mão","size":"Folha 38 × 55,5 cm","credit":"Doação de F. G. Waller","p":["Uma prancha de NIPPON, a grande obra que o médico de origem alemã Philipp Franz von Siebold publicou em Leiden a partir do que viu na feitoria neerlandesa de Nagasáqui (1823–30). Traz «TAB. I» em cima à direita e «KOORAI» (Coreia) em baixo, com «uma família de pescadores» em neerlandês e alemão. Erxleben desenhou-a na pedra; a prancha nomeia o desenhador como «Toioske».","Quatro homens sentados no chão rodeiam um tabuleiro; à esquerda uma mulher leva uma criança pela mão, à direita um homem de pé segura um pau comprido e uma bolsa. À frente, no chão, um chapéu preto de aba larga (gat). O tabuleiro mostra uma quadrícula e pedras redondas, por isso provavelmente é go (baduk em coreano), embora o registo diga apenas «um jogo de tabuleiro»."],"spots":[["O tabuleiro","Quadrícula com pedras redondas: provavelmente uma partida de go."],["O chapéu preto","Um chapéu preto de aba larga (gat) no chão."],["Mãe e filho","Uma mulher com uma criança pela mão observa o jogo."],["O homem de pé","De pé, com um pau comprido e uma bolsa."],["O homem inclinado","De casaco azul, espreita o tabuleiro."],["O título","«KOORAI» (Coreia), com «uma família de pescadores» em neerlandês e alemão."]]},"cairo":{"title":"Pessoas em volta de um jogo de tabuleiro à porta de um café (Cairo)","artist":"Délié & Béchard (Hippolyte Délié e Émile Béchard)","date":"c. 1869–90","place":"Egito (Cairo)","game":"Jogo de tabuleiro (provavelmente xadrez)","medium":"Prova em albumina","size":"10,8 × 16,4 cm","credit":"","p":["Uma fotografia de Hippolyte Délié e Émile Béchard, fotógrafos franceses com estúdio no Cairo. O cartão tem impresso o nome do estúdio, «junto ao jardim de Ezbekiya», e «Cairo (Egito)». Os viajantes compravam fotografias assim como recordação do Egito.","Homens sentados no chão diante de uma loja com janela de gelosia rodeiam um tabuleiro sobre um suporte baixo. Peças altas erguem-se no tabuleiro, por isso provavelmente é xadrez (shatranj em árabe), embora o registo do museu diga apenas «um jogo de tabuleiro». Todos ficam imóveis para a longa exposição."],"spots":[["Tabuleiro e peças","O tabuleiro num suporte baixo, com peças altas: provavelmente xadrez."],["A janela de gelosia","Uma janela com gelosia de madeira, típica das casas antigas do Cairo."],["O homem do bordão","Sentado com um bordão, vê o jogo."],["O cesto","Um cesto entrançado no chão."],["A criança que observa","Uma criança espreita o tabuleiro por trás."],["O nome do estúdio","«AU JARDIN DE L’ESBÉKIEH» e «CAIRE (EGYPTE)» no cartão."]]},"vanmour":{"title":"Reunião de arménios a jogar às cartas","artist":"Jean-Baptiste Vanmour","date":"c. 1720–37","place":"Império Otomano (Istambul)","game":"Cartas","medium":"Óleo sobre tela","size":"44,5 × 58,5 cm","credit":"","p":["Nascido na Flandres, Vanmour foi para Istambul em 1699 com o embaixador de França e viveu na cidade até morrer, pintando cerimónias da corte e a vida quotidiana dos seus habitantes. O museu indica que as roupas dos homens os identificam como arménios.","À luz de uma grande vela, homens e mulheres jogam às cartas à volta de uma mesa coberta com um pano vermelho. Há cartas dadas sobre a mesa e alguns estudam as que têm na mão. No canto esquerdo, uma velha fia. O registo não diz que jogo é."],"spots":[["Cartas na mesa","Cartas sobre a mesa de pano vermelho."],["A grande vela","Uma só vela ilumina todo o grupo."],["A velha a fiar","Uma velha fia no canto esquerdo."],["Mulher com as cartas","À direita, uma mulher olha para as suas cartas."],["O homem de peles","Um homem com casaco debruado a peles; a roupa marca-os como arménios."],["Debruçado sobre a mesa","Alguém se debruça sobre a mesa com cartas na mão."]]},"algiers":{"title":"Três homens a jogar um jogo de tabuleiro (Argel)","artist":"Anónimo","date":"1851–1900","place":"Argélia (Argel)","game":"Jogo de tabuleiro (provavelmente gamão)","medium":"Prova em albumina","size":"14,0 × 10,0 cm","credit":"","p":["Uma fotografia anónima com a inscrição manuscrita «Alger» (Argel) por baixo da imagem. Com cadeiras e uma mesinha diante de um fundo liso, foi provavelmente tirada num estúdio. Viajantes e colecionadores compravam fotografias assim de gentes do Norte de África.","Dois homens estão frente a frente diante de um tabuleiro com rebordo, e o da direita estende a mão para uma peça. Há peças redondas empilhadas no tabuleiro, por isso provavelmente é gamão (chamado ali tawla, entre outros nomes), embora o registo diga apenas «um jogo de tabuleiro». Na mesinha da frente estão os utensílios do café."],"spots":[["Tabuleiro e peças","Um tabuleiro com rebordo e peças redondas empilhadas."],["O que observa de pé","Um homem de faixa à cintura vê o jogo de pé, atrás."],["O velho, à esquerda","Um homem idoso de turbante, pensativo."],["O homem da direita","Com um pano branco na cabeça, debruça-se sobre o tabuleiro."],["Os utensílios do café","Tabuleiro e chávenas numa mesinha rendilhada."],["A mão que joga","A mão do jogador da direita, prestes a pegar numa peça."]]},"circo":{"title":"Jogo do Circo (Juego del Circo)","artist":"Manuel Manilla (?)","date":"Sem data","place":"México","game":"Jogo de apostas com dois dados","medium":"Gravura em relevo ou fotogravura em papel velino castanho-claro","size":"26,2 × 35,0 cm","credit":"","p":["Uma folha de jogo atribuída, com ponto de interrogação, ao gravador mexicano Manuel Manilla. Em baixo à direita aparece quem a vendia, a estamparia «El Teatro», com a morada. Folhas baratas assim vendiam-se na rua e, ao que parece, jogavam-se tal como estavam.","Ao centro há uma tenda de circo, rodeada de cavaleiros acrobatas, uma torre humana, um homem forte e outros, cada um com um número de 2 a 12. A «Esplicacion» no canto superior esquerdo diz que todos podem jogar, crianças também: lançam-se dois dados e põe-se a aposta na casa que sai, ou leva-se o que já lá está. Quem tirar doze leva tudo."],"spots":[["A tenda","O título «JUEGO DEL CIRCO» e a tenda, que é a casa 12."],["As regras","As regras, sob o título «ESPLICACION»."],["A cavaleira","Uma bailarina num cavalo a galope: casa 6."],["A torre humana","Um homem de pé nos ombros de outro: casa 4."],["O homem forte","Um homem a erguer um peso em forma de canhão: casa 8."],["O nome da estamparia","«De venta, Estampería “El Teatro”» e a morada."]]},"loteria":{"title":"Jogo de lotería","artist":"José Guadalupe Posada","date":"1880–1913","place":"México","game":"Lotería (jogo de figuras cantadas)","medium":"Gravura em relevo ou fotogravura em papel velino castanho-claro","size":"30,0 × 40,0 cm","credit":"","p":["O gravador mexicano Posada desenhou imensas imagens para o editor da Cidade do México Antonio Vanegas Arroyo, cujas folhas baratas levavam notícias, canções e jogos. Esta tem o título «JUEGO DE LOTERIA» e o nome de Vanegas Arroyo.","Trinta e oito pequenas figuras com nome enchem a folha: a estrela, a lua, o escorpião, o diabo, a caveira, o galo, a tipografia e outras. Na lotería, parecida com o bingo, quem «canta» tira cartas e diz as figuras, e os jogadores marcam-nas na sua tábua com feijões ou outra coisa. A folha seria provavelmente recortada em cartas."],"spots":[["Título e editor","«JUEGO DE LOTERIA» e o nome da casa de Vanegas Arroyo."],["A estrela","«ESTRELLA», a primeira figura em cima à esquerda."],["A lua","«LUNA», um crescente com rosto."],["A morte","«MUERTE»: um esqueleto com foice a tocar flauta."],["O tlachiquero","«TLACHIQUERO»: um homem que recolhe a seiva do agave."],["A tipografia","«IMPRENTA»: operários numa prensa, onde se faziam folhas assim."]]},"jeupol":{"title":"«Jeu polonais», ou tabuleiro de damas","artist":"Anónimo","date":"1833–1900","place":"Bélgica ou Países Baixos","game":"Damas (tabuleiro de 10 × 10)","medium":"Xilogravura com texto tipográfico","size":"32,2 × 39,6 cm","credit":"","p":["Uma folha solta com título em francês e neerlandês, «JEU POLONAIS OF DAMSPEL». «Jeu polonais» (o jogo polaco) era o nome francês das damas no tabuleiro de 10 × 10. Em cima à direita está o número de série do editor, «n. 106».","Como diz o registo do museu, há 100 casas, 50 brancas e 50 pretas, com cercaduras decorativas à esquerda e à direita. Não há peças impressas, por isso era provavelmente um tabuleiro barato usado tal como estava, com feijões ou botões. O papel conserva as dobras."],"spots":[["O título","As palavras «JEU POLONAIS OF DAMSPEL»."],["O número de série","O número do editor, «n. 106»."],["A cercadura esquerda","Uma coluna de rosetas."],["A cercadura direita","O mesmo motivo do outro lado."],["As cem casas","O tabuleiro de 10 × 10; as casas escuras são tracejadas."],["A dobra","Uma dobra no papel; talvez se levasse dobrado."]]},"dkaart":{"title":"Dominó e cartas para recortar","artist":"Anónimo (Brepols)","date":"1800–1833","place":"Bélgica (Turnhout)","game":"Dominó e cartas","medium":"Xilogravura colorida a azul, vermelho e amarelo; texto tipográfico","size":"34,3 × 41,9 cm","credit":"","p":["Segundo o registo do museu, a folha imprime 32 cartas de jogar e 28 peças de dominó para recortar. É o número 114 do catálogo do editor Brepols, com o revendedor «D. Pouwels, Bergen-op-Zoom» em baixo. O título está em neerlandês e francês.","À esquerda, as 28 peças do duplo branco ao duplo seis empilham-se em triângulo. À direita há 32 cartas, do sete ao dez mais figuras e ases de cada naipe: um baralho para jogos como o piquet. Como ninguém a recortou, vemo-la tal como saiu da prensa."],"spots":[["O título","As palavras «DOMINO EN KAARTSPEL»."],["Duplo branco","O topo do triângulo: a peça sem pintas."],["Duplo seis","A peça maior, no fim da última fila."],["Ás de espadas","A segunda carta da coluna esquerda."],["Uma figura","Um rei colorido a vermelho, azul e amarelo."],["O revendedor","«D. POUWELS, Bergen-op-Zoom» em baixo."]]},"apen":{"title":"Dois macacos a jogar trictrac","artist":"Quirin Boel, segundo David Teniers","date":"1635–1690","place":"Flandres","game":"Trictrac (parente do gamão)","medium":"Água-forte","size":"11,0 × 14,5 cm","credit":"","p":["Uma de uma série, frontispício e seis estampas, em que macacos imitam ocupações humanas. Em baixo à esquerda lê-se «D. Teniers inventou e publicou, com privilégio»: Quirin Boel gravou o desenho do pintor flamengo Teniers.","Como descreve o registo do museu, dois macacos estão sentados no chão com um tabuleiro de trictrac entre eles. O da esquerda bebe vinho por um copo; o da direita, de chapéu com pena de galo, estende a mão para uma peça. Provavelmente troça de quem se entrega à bebida e ao jogo."],"spots":[["O tabuleiro","Um tabuleiro dobrável no chão, com as suas casas e peças."],["O macaco da esquerda","Um macaco de casaco, sentado diante do jogo."],["O copo","O copo erguido pelo macaco da esquerda."],["O chapéu com pena","Uma pena de galo no chapéu do da direita."],["O jarro","Um jarro aos pés do macaco da esquerda."],["A inscrição","«D Teniers in et excud cum privilegio»."]]},"dstereo":{"title":"Homens a jogar dominó a uma mesa (estereografia)","artist":"Anónimo","date":"1850–1880","place":"Desconhecido (inscrição em neerlandês)","game":"Dominó","medium":"Prova em albumina (estereografia)","size":"8,5 × 17,0 cm","credit":"","p":["Uma estereografia: duas fotografias quase idênticas lado a lado. Vistas num estereoscópio, fundem-se numa só cena com profundidade. Na margem esquerda lê-se, à mão, «Het dominospel» (o jogo do dominó).","Puseram uma mesa ao sol diante de um edifício, e homens em mangas de camisa seguram as suas peças. Dois veem o jogo de pé; o da direita usa um barrete branco. Como todos tinham de ficar imóveis, a cena foi provavelmente arranjada para a câmara."],"spots":[["As peças na mesa","Peças de dominó viradas para baixo nas mãos."],["O do barrete branco","Sentado à direita, com as suas peças."],["O do lenço","De pé, a olhar o jogo de cima."],["O da esquerda","Um jovem apoiado no cotovelo, com as suas peças."],["A inscrição","«Het dominospel.» escrito na margem esquerda."],["A segunda imagem","A foto da direita, tirada de um ponto um pouco deslocado: juntas veem-se em relevo."]]},"gojo":{"title":"Duas mulheres a jogar go","artist":"Anónimo","date":"1870–1891","place":"Japão","game":"Provavelmente go","medium":"Prova em albumina colorida à mão","size":"9,0 × 13,5 cm","credit":"","p":["Uma fotografia a preto e branco colorida à mão com pincel. Fotografias assim faziam-se em estúdios de Yokohama e de outros lugares como recordações para estrangeiros. Esta estava colada num álbum de fotografias de uma viagem a Manila.","Diante de um arranjo de tokonoma e de um biombo, duas mulheres sentam-se de cada lado de um tabuleiro com pés, e a da esquerda coloca uma pedra. Há pedras brancas e pretas no tabuleiro, por isso provavelmente é go, embora o registo do museu diga «um jogo de tabuleiro». Na bandeja da frente há doces e taças."],"spots":[["Tabuleiro e pedras","Um tabuleiro grosso com pés e pedras brancas e pretas."],["A mão que joga","A mulher da esquerda coloca uma pedra."],["A mulher da esquerda","Volta-se para nós; o obi tem um grande laço."],["A mulher da direita","De quimono às riscas, a mão junto ao tabuleiro."],["Bandeja e taças","Doces e chávenas à frente."],["As flores","Um vaso de flores num suporte, ao fundo."]]},"meade":{"title":"Dois homens a jogar xadrez","artist":"Charles Richard Meade e Henry William Mathew Meade","date":"1852","place":"Estados Unidos","game":"Xadrez","medium":"Daguerreótipo","size":"6,9 × 8,3 cm","credit":"","p":["Um daguerreótipo do estúdio dos irmãos Meade, fotógrafos nascidos em Inglaterra que trabalharam na América. O daguerreótipo forma a imagem diretamente numa chapa de cobre prateada, por isso cada um é único e não se pode reproduzir; este está num estojo de couro atrás de uma moldura dourada.","Dois jovens estão diante de um tabuleiro num pequeno suporte; o da esquerda tem os dedos numa peça. O da direita, com a mão no peito, estuda o tabuleiro. Como tinham de ficar imóveis muito tempo, a jogada é provavelmente posada."],"spots":[["O tabuleiro","O tabuleiro e as peças brancas num suporte coberto de tecido florido."],["O da esquerda","Com os dedos numa peça."],["O da direita","Olha o tabuleiro de cima."],["A mão no peito","A mão pensativa do da direita."],["O tecido","Um pequeno suporte coberto de tecido florido."],["A moldura dourada","A moldura e o estojo que protegem a chapa."]]},"weiqidai":{"title":"Paisagem com imortais taoístas a jogar weiqi","artist":"Atribuído a Dai Jin","date":"Dinastia Ming, séculos XV–XVI","place":"China","game":"Weiqi (go)","medium":"Rolo vertical; tinta e cores sobre seda","size":"175,2 × 106,7 cm","credit":"","p":["Um grande rolo vertical atribuído ao pintor Ming Dai Jin (c. 1388–1462). Natural de Zhejiang e conhecido pelas suas paisagens vigorosas, foi mais tarde tido como fundador da escola Zhe. Sob falésias altíssimas e uma grande árvore, as figuras são pequenas.","No chão, à sombra, dois imortais sentam-se diante de um tabuleiro de weiqi quadriculado, com um prato de fruta e um jarro ao lado. A figura agachada à esquerda lembra o lenhador que viu imortais jogar na montanha até o cabo do machado apodrecer (a lenda de Lanke), embora o título do museu fale apenas de imortais a jogar weiqi."],"spots":[["O tabuleiro","Um tabuleiro com rebordo e uma grelha fina."],["O imortal barbudo","Um imortal de longa barba, sentado com calma."],["O imortal do barrete azul","Debruçado sobre o tabuleiro; junto ao joelho, uma taça de pedras."],["A figura agachada","Espreita o tabuleiro da esquerda; talvez o lenhador da lenda."],["Fruta e jarro","Um prato e um jarro para lá do tabuleiro."],["Assinatura e selos","Uma assinatura e dois selos vermelhos em cima à direita."]]},"reise":{"title":"A viagem à volta do mundo, por mar e por terra","artist":"Anónimo","date":"Século XIX","place":"Provavelmente terras de língua alemã","game":"Jogo de percurso com um dado, a dinheiro","medium":"Litografia","size":"42,5 × 33,7 cm","credit":"","p":["Uma folha de jogo com título em alemão «A viagem à volta do mundo, por água e por terra: um novo e divertido jogo de dados». Um tabuleiro redondo tem casas de 1 a 41, com imagens de um balão, veleiros, um vapor, uma locomotiva, gentes de várias nações e mais. Tem o número «No. 107» em baixo à direita.","Por baixo estão as regras em alemão, inglês, neerlandês e francês. Cada jogador paga primeiro 15 marcos à «bolsa da viagem» comum; depois lança um dado à vez e avança o seu marcador. Cair numa imagem grande ganha 2 marcos, um número sem imagem custa 2 de multa, e quem chega ao 41 leva todo o resto."],"spots":[["41: a diligência","A meta ao centro: uma diligência com viajantes e cocheiro."],["1: o inglês","A casa de partida, «Engländer» de cartola."],["O balão","Uma casa com um balão no céu."],["O veleiro","Um navio de velas enfunadas."],["A locomotiva","Uma locomotiva a vapor a deitar fumo."],["As regras","As regras, impressas em quatro línguas."]]},"huchten":{"title":"Os dados pela vida ou pela morte","artist":"Jan van Huchtenburg","date":"1680–1720","place":"Países Baixos","game":"Dados","medium":"Óleo sobre tela","size":"67,5 × 76,0 cm","credit":"","p":["Obra do pintor holandês Jan van Huchtenburg (1647–1733), conhecido pelas batalhas, assinada em baixo à esquerda. O título do museu é «O jogo de dados pela vida». Fora de uma fortaleza, dois presos lançam os dados sobre um tambor, rodeados de oficiais e soldados.","Ao fundo à direita ergue-se uma forca, e da muralha à esquerda outros soldados observam. Provavelmente mostra soldados condenados a tirar à sorte com dados quem será executado. Um preso aponta para o tambor; o outro, ajoelhado, olha para o lançamento."],"spots":[["Tambor e dados","Um tambor serve de mesa para lançar os dados."],["O preso que aponta","De pé, aponta para o tambor."],["O preso ajoelhado","De camisa branca, debruçado sobre o tambor."],["O oficial a cavalo","De chapéu, olha do alto do cavalo."],["A forca","A forca, em cima à direita."],["Soldados na muralha","Soldados que observam do alto do muro."]]},"vertu":{"title":"O jogo da virtude (Spel der Deugd)","artist":"Jan Gerritsz. Visser (concebido por J. Voorman)","date":"1798","place":"Países Baixos","game":"Jogo de apostas com dois dados","medium":"Gravura a buril, água-forte e tipografia","size":"56,9 × 38,0 cm","credit":"","p":["Uma grande folha de jogo com título em neerlandês e francês, «O jogo da virtude». Num templo de colunas, a Virtude está sentada ao centro, com a Prosperidade de pé à esquerda e a Pobreza à direita. Nas colunas há medalhões de virtudes como a Sinceridade, a Gratidão e o Amor, e nos pedestais vícios como a Avareza, o Orgulho e a Preguiça.","Segundo as regras em baixo, joga-se com dois dados ou tirando sortes. Com dados, os jogadores apostam 63 no total e lançam à vez seguindo o curso do sol. Cada lançamento corresponde a uma virtude ou vício: o duplo seis, a Virtude, leva o pote, e o duplo um, o Vício, paga oito. Sob cada imagem, «T» é o que se recebe e «B» o que se paga."],"spots":[["O título","«SPEL DER DEUGD» no frontão."],["A Virtude","A Virtude no trono central; o duplo seis leva tudo."],["A Prosperidade","A Prosperidade com a cornucópia."],["O Vício","O duplo um, o Vício: uma criança a erguer uma taça."],["A Avareza","A Avareza no pedestal; «B» e os dados dizem o que se paga."],["As regras","As regras, impressas cerradas em baixo."]]},"charros":{"title":"Os charros contrabandistas: jogo de dados","artist":"José Guadalupe Posada","date":"Sem data","place":"México","game":"Jogo de percurso com três dados","medium":"Litografia","size":"29,9 × 40,4 cm","credit":"","p":["Um jogo de percurso ilustrado por Posada, intitulado «LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS» (Os charros contrabandistas / Jogo de dados). Em baixo vem o nome da Imprenta de A. Vanegas Arroyo, México, e Posada assinou em baixo à direita. Os charros, cavaleiros mexicanos, galopam de sombreiro nos cantos.","Casas redondas debruadas de corda serpenteiam por todo o tabuleiro, com animais, pessoas, um comboio e mais. A «Explicação» no canto superior direito diz que se joga com três dados. Três uns no primeiro lançamento ganham; cair na caveira perde; no veado recebe-se do fundo, nos ladrões paga-se, e no leão fica-se parado até que outro venha."],"spots":[["O título","«LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS»."],["A explicação","As regras, sob «EXPLICACION»."],["Os jogadores","Gente à volta de uma mesa, a jogar num tabuleiro, em baixo à esquerda."],["Os dados","Três dados desenhados a meio do tabuleiro."],["O charro a cavalo","Um charro a galope a girar o laço."],["A tipografia","«IMPRENTA DE A. VANEGAS ARROYO, MÉXICO»."]]},"snuffwq":{"title":"Frasco de rapé com figuras a jogar weiqi","artist":"China","date":"Dinastia Qing, marca e período Daoguang (1820–50)","place":"China","game":"Weiqi (go)","medium":"Porcelana pintada com esmaltes sobre vidrado","size":"Alt. 5,7 cm","credit":"","p":["Um frasquinho para levar rapé na China Qing. O registo do museu indica uma marca do reinado Daoguang e data-o de 1820–50. No seu corpo de porcelana branca, com uns seis centímetros, há uma paisagem montanhosa e figuras pintadas com esmaltes.","Junto a uma rocha em forma de gruta, dois anciãos sentam-se diante de um tabuleiro de weiqi num suporte azul; o da esquerda vai colocar uma pedra. Atrás dele observa uma criança com um bordão. O tema evoca provavelmente a lenda do lenhador que viu imortais a jogar."],"spots":[["O tabuleiro","Um tabuleiro num suporte azul, com grelha fina."],["O ancião barbudo","De túnica roxa, estende a mão para o tabuleiro."],["O ancião em frente","Sentado à direita, de mão erguida."],["A criança do bordão","Observa por trás."],["A gruta","Uma rocha em forma de gruta."],["A tampa","Uma tampa verde."]]},"ostade":{"title":"Jogadores de trictrac numa taberna","artist":"Adriaen van Ostade","date":"1653","place":"Países Baixos (Haarlem)","game":"Trictrac (parente do gamão)","medium":"Água-forte","size":"8,5 × 7,4 cm","credit":"","p":["Uma água-forte do tamanho da palma da mão, do pintor de Haarlem Ostade, conhecido pelas cenas camponesas, assinada «A. ostade» em baixo. Numa taberna escura, a luz de uma janela de chumbo cai sobre as pessoas.","Na mesa da esquerda dois homens defrontam-se num tabuleiro de trictrac, enquanto um terceiro espreita de trás. À direita, um homem encosta-se à parede com um copo na mão. Um grande jarro jaz no chão; parece uma tarde preguiçosa na taberna."],"spots":[["O tabuleiro","Um tabuleiro de trictrac na mesa."],["O jogador da esquerda","Um homem de chapéu diante do tabuleiro."],["O jogador da direita","Debruçado sobre o tabuleiro."],["O que espreita","Um homem de pé atrás, a observar."],["O que descansa","Sentado junto à parede, de copo na mão."],["A janela de chumbo","Uma janela de losangos por onde entra a luz."]]},"lenain":{"title":"Os jogadores de dados","artist":"Seguidor de Mathieu Le Nain","date":"1630–1680","place":"França","game":"Dados","medium":"Óleo sobre tela","size":"92,8 × 119,7 cm","credit":"","p":["Obra de um seguidor de Mathieu, o mais novo dos irmãos franceses Le Nain. O museu nota que um esboço de composição semelhante, de Gabriel de Saint-Aubin, está na Bibliothèque nationale em Paris.","Três homens rodeiam uma pequena mesa redonda ao ar livre e lançam os dados; outros dois observam, e o da esquerda abraça uma garrafa. À direita há dois galgos esguios, e ao fundo abre-se uma vasta paisagem. As coisinhas brancas na mesa são os dados."],"spots":[["Dados na mesa","Dados sobre a mesa redonda."],["O do chapéu claro","Sentado, estende a mão para ver o lançamento."],["O de negro","Um jovem de pé, mão na anca."],["O rapaz de trás","Vê o jogo por trás da mesa."],["O da garrafa","À esquerda, sorri para nós."],["Os dois galgos","Cães esguios à direita."]]},"tunisie":{"title":"Partida de cartas diante de um café árabe (secção tunisina, Exposição de Antuérpia)","artist":"Anónimo (impresso por Ch. Bernhoeft)","date":"1894","place":"Bélgica (Antuérpia)","game":"Cartas","medium":"Fototipia","size":"15,4 × 21,6 cm","credit":"","p":["Uma de um conjunto de 49 estampas da Exposição Universal de Antuérpia de 1894, com «EXPOSITION UNIVERSELLE D’ANVERS 1894» em cima e «Tunísia: partida de cartas diante de um café árabe» em baixo. Foi impressa por Bernhoeft, fotógrafo da corte no Luxemburgo.","Foi tirada numa praça com cúpulas e uma torre construída para a secção tunisina da exposição. Homens em trajes tunisinos jogam às cartas em mesinhas de azulejo; um fuma narguilé e há um tabuleiro de chávenas. À direita sentam-se visitantes de fato: provavelmente era uma exibição da vida de uma terra distante."],"spots":[["A mesa de cartas","Homens com cartas à volta de uma mesinha de azulejo."],["O narguilé","O tubo do narguilé do homem da esquerda."],["Visitantes de fato","Homens de fato sentados à direita, provavelmente visitantes."],["O tabuleiro de chávenas","Pequenas chávenas debaixo da mesa."],["Cúpulas e torre","Edifícios de estilo tunisino erguidos para a feira."],["A legenda","«TUNISIE» e «PARTIE DE CARTES DEVANT UN CAFÉ ARABE»."]]},"laghouat":{"title":"Caídes dos arredores de Laghouat","artist":"Anónimo","date":"1880–1890","place":"Argélia (arredores de Laghouat)","game":"Provavelmente dominó","medium":"Prova em albumina","size":"20,9 × 27,0 cm","credit":"","p":["Uma fotografia intitulada «Tipos argelinos: caídes dos arredores de Laghouat», colada num álbum e com o número «239» impresso. Caíde era o título de um chefe local na Argélia sob domínio francês.","Homens de túnicas brancas, sentados numa esteira diante de um muro de taipa, dispõem peças compridas sobre uma mesinha baixa. Pela forma como estão dispostas, é provavelmente dominó, embora o registo do museu diga apenas «um jogo». À frente há um tabuleiro de chá e as babuchas que tiraram."],"spots":[["Peças na mesinha","Peças compridas em fila sobre a mesa."],["O tabuleiro de chá","Copos e bule num tabuleiro à frente."],["As babuchas","Calçado deixado junto à esteira."],["A figura de pé","Alguém de pé junto ao muro, a observar."],["O muro de taipa","O muro de terra áspero ao fundo."],["A esteira","A esteira entrançada onde se sentam."]]},"hangong":{"title":"Damas do palácio (Manhã de primavera no palácio Han), pormenor","artist":"Cópia segundo Qiu Ying","date":"Dinastia Qing (1644–1911)","place":"China","game":"Weiqi (go)","medium":"Rolo horizontal; tinta e cor sobre seda","size":"36,2 × 454,4 cm (rolo inteiro)","credit":"","p":["Um pormenor de um rolo horizontal com mais de quatro metros e meio, cópia do período Qing de uma composição do pintor Ming Qiu Ying (1494–1552). Num palácio, num dia de primavera, damas, raparigas e criadas andam de baloiço, jogam, admiram peónias, fazem música, tocam qin e dão de comer a um papagaio e aos peixes.","Nesta cena, duas mulheres enfrentam-se diante de um tabuleiro de weiqi atrás de uma balaustrada, enquanto outras se inclinam para ver. À frente há uma pedra de letrado numa taça em forma de lótus, e criadas levam instrumentos e embrulhos. Como nota o museu, o rolo idealiza a vida das mulheres nos aposentos interiores."],"spots":[["O tabuleiro","Um tabuleiro de weiqi numa mesa atrás da balaustrada."],["A que coloca uma pedra","Uma mulher de lilás que estende a mão ao tabuleiro."],["As que observam","Mulheres inclinadas sobre o jogo."],["A dama do leque","Uma mulher com um leque redondo entre as colunas."],["A pedra de letrado","Uma rocha azul numa taça em forma de lótus."],["A criada com o instrumento","Uma criada que leva o que é provavelmente uma pipa."]]},"homerbg":{"title":"Gamão","artist":"Winslow Homer","date":"c. 1877","place":"Estados Unidos","game":"Gamão","medium":"Gravura em madeira de topo","size":"","credit":"","p":["Uma gravura em madeira segundo um desenho do pintor americano Winslow Homer (1836–1910), que em jovem fez muitas ilustrações para estampas assim. Por baixo lê-se «396.—BACKGAMMON.—WINSLOW HOMER.», pelo que provavelmente pertencia a uma série numerada num livro ou revista.","Duas mulheres sentadas frente a frente num sofá ornamentado jogam gamão num tabuleiro pousado no colo de ambas. Sobre o tabuleiro há um objeto redondo e branco, embora não se perceba o que é. As pregas das saias compridas e os braços em voluta do sofá estão gravados em linhas finas."],"spots":[["O tabuleiro","O tabuleiro pousado no colo das duas."],["A mulher da esquerda","De cabelo apanhado, estende a mão ao tabuleiro."],["A mulher da direita","Inclina-se para estudar o tabuleiro."],["O braço do sofá","Um braço em voluta."],["As saias","Saias compridas com pregas em linhas finas."],["A legenda","«396.—BACKGAMMON.—WINSLOW HOMER.» em baixo."]]},"chessst":{"title":"Homem e mulher a jogar xadrez (estereografia)","artist":"Anónimo","date":"1852–1858","place":"Desconhecido","game":"Xadrez","medium":"Estereografia colorida","size":"8,3 × 16,5 cm","credit":"","p":["Um par de fotografias montadas como estereografia, conhecida em inglês como «The Chess Players». Vistas num estereoscópio, o tabuleiro e as peças parecem saltar em relevo. A cor foi acrescentada sobre a imagem a preto e branco, na cortina vermelha e no vestido amarelo.","A mulher de amarelo tem a mão numa peça, enquanto o homem à frente, visto de costas, estuda o tabuleiro. Há peças vermelhas e brancas a meio do jogo, mas a cena foi provavelmente arranjada num estúdio. Estereografias de cenas domésticas como esta vendiam-se muito em meados do século XIX."],"spots":[["Tabuleiro e peças","Peças vermelhas e brancas no tabuleiro xadrezado."],["A mão que joga","A mão da mulher numa peça."],["A mulher","De vestido amarelo e gola branca, olha o tabuleiro."],["O homem","Sentado de costas para nós."],["A cortina vermelha","A cortina colorida ao fundo."],["A segunda imagem","A vista da direita; no estereoscópio o par ganha profundidade."]]},"corrida":{"title":"Jogo de dados da tourada (Corrida de Toros)","artist":"José Guadalupe Posada","date":"1898","place":"México","game":"Jogo de percurso com dois dados, a dinheiro","medium":"Fotogravura em relevo sobre papel velino","size":"40,4 × 30,0 cm","credit":"","p":["Um jogo de percurso ilustrado por Posada, intitulado «CORRIDA DE TOROS». As casas seguem em espiral e mostram por ordem os lances e momentos da tourada, da casa 1, por fora, até ao centro. Ao meio há uma praça de touros, e em baixo o nome da tipografia de Antonio Vanegas Arroyo.","Segundo a «Explicação» em rodapé, jogam duas ou mais pessoas, cada uma com a sua aposta, lançando dois dados. O 5, «salto à vara», vai ao 10; o 12, «colhida do picador», paga e fica sem jogar; o 28, «passe de peito», volta ao início. Quem chega ao 32, «arrasto do touro», leva todas as apostas."],"spots":[["O título","As palavras «CORRIDA DE TOROS»."],["A praça","A praça de touros no centro da espiral."],["A casa 1","A partida, à entrada da espiral."],["A cabeça do touro","Uma cabeça de touro com cornos, em cima à direita."],["O toureiro","O retrato de um toureiro, em baixo à esquerda."],["A explicação","A «EXPLICACION» impressa no rodapé."]]},"ambrocards":{"title":"Três homens a jogar às cartas","artist":"Autor desconhecido (norte-americano)","date":"1865","place":"Estados Unidos","game":"Cartas","medium":"Ambrótipo","size":"14,0 × 11,0 cm","credit":"","p":["O ambrótipo é um negativo fino em vidro com fundo negro por trás, de modo que se vê como positivo. Mais barato do que o daguerreótipo, foi muito usado na América nas décadas de 1850 e 1860. Este está atrás de uma moldura dourada num estojo forrado de veludo vermelho.","Diante de um fundo liso, três homens rodeiam uma mesinha com as cartas na mão. O da esquerda usa chapéu de coco e o da direita um boné, ambos de charuto na boca; o do centro, de casaco escuro, olha para nós. Provavelmente posaram como se estivessem a meio do jogo."],"spots":[["As mãos","Mãos com cartas sobre a mesa."],["O do chapéu de coco","À esquerda, de charuto."],["O do centro","De casaco escuro, olha para nós."],["O do boné","À direita, de charuto."],["A moldura dourada","A moldura dourada estampada à volta da imagem."],["O estojo","O estojo forrado de veludo vermelho."]]},"morphy":{"title":"Paul Morphy, o campeão de xadrez","artist":"Winslow Homer","date":"1859","place":"Estados Unidos","game":"Xadrez","medium":"Gravura em madeira de topo","size":"","credit":"","p":["Um retrato gravado em madeira com a legenda «PAUL MORPHY, THE CHESS CHAMPION», segundo um desenho de Winslow Homer (1836–1910), então um jovem ilustrador. Morphy (1837–1884), de Nova Orleães, percorreu a Europa em 1858–59 vencendo um mestre após outro e voltou para casa famoso.","O jovem Morphy, sentado, apoia a mão esquerda na borda de um tabuleiro, junto a um rei, uma torre, peões e outras peças. Feito em 1859, quando regressou como celebridade, foi provavelmente impresso como ilustração num jornal ou revista."],"spots":[["As peças","Um rei, uma torre, peões e outras no tabuleiro."],["A mão no tabuleiro","A mão esquerda na borda do tabuleiro."],["O rosto de Morphy","O campeão, mal passados os vinte."],["O laço","Um colarinho bem arranjado."],["A mão no joelho","A mão direita pousada no joelho."],["O título","«PAUL MORPHY, THE CHESS CHAMPION» em baixo."]]},"dutton":{"title":"A família Dutton na sala de Sherborne Park, Gloucestershire","artist":"Johann Zoffany","date":"c. 1772","place":"Inglaterra","game":"Cartas","medium":"Óleo sobre tela","size":"101,5 × 127,0 cm","credit":"","p":["Obra de Johann Zoffany (1733–1810), pintor nascido na Alemanha que fez carreira em Inglaterra. O «conversation piece», que retrata uma família de modo informal, nasceu na Inglaterra do século XVIII e foi muito popular. A cena é a sala de Sherborne Park, em Gloucestershire.","Segundo o museu, pai e filha, mãe e filho estudam a próxima jogada num jogo de cartas. A família tinha perdido há pouco um ente querido, por isso os pais vestem luto carregado, de preto, e os filhos meio-luto em lilás, branco e cinzento."],"spots":[["A mesa de jogo","Uma mesa de pano verde com cartas."],["O pai","De preto, com as suas cartas."],["A filha","De branco, a olhar o seu jogo."],["O filho","De cinzento, com as suas cartas."],["A mãe","De luto preto."],["A lareira","Uma lareira de mármore acesa."]]},"whist":{"title":"Os académicos de Natal: uma partida combinada de whist","artist":"James Bretherton (provavelmente segundo H. W. Bunbury)","date":"1773","place":"Inglaterra","game":"Whist (cartas)","medium":"Água-forte","size":"26,5 × 39,6 cm","credit":"","p":["Segundo o museu, uma sátira aos académicos de Cambridge. Em baixo à esquerda parece ler-se «H. W. Bunbury del. 1772» e à direita «J. Bretherton f.»; foi publicada em 1773 por uma loja de New Bond Street, em Londres. Na parede pendem barretes académicos.","Quatro cavalheiros jogam whist enquanto fazem caretas uns aos outros. O whist joga-se em dois pares, por isso a «partida combinada» do título é provavelmente um trocadilho. Atrás, um homem faz um gesto trocista com os dedos sobre a cabeça de outro. Perto estão dois criados e dois cães."],"spots":[["Cartas na mesa","Cartas jogadas sobre a mesa."],["O académico de peruca","Um sábio de grande peruca, mão junto ao peito."],["O gesto dos dedos","Um homem atrás ergue os dedos sobre a cabeça de outro."],["A criada","Uma criada de chapéu com uma bandeja."],["Os barretes","Barretes universitários pendurados na parede."],["O cão da direita","Um cãozinho a ladrar em baixo à direita."]]},"hey":{"title":"Três homens a jogar xadrez","artist":"Paul Hey","date":"1877–1952","place":"Alemanha","game":"Xadrez","medium":"Gravura (provavelmente água-forte)","size":"19,3 × 26,0 cm","credit":"","p":["Uma gravura do pintor e ilustrador alemão Paul Hey (1867–1952). Três homens idosos debruçam-se sobre o mesmo tabuleiro; linhas finas sobrepostas desenham as rugas e as barbas brancas.","Como regista o museu, o da esquerda tem a mão no queixo e o da direita segura um charuto enquanto estende a mão sobre as peças. À esquerda da mesa há duas chávenas de café, um copo e uma caixa de fósforos. Provavelmente uma partida num café."],"spots":[["O tabuleiro","Tabuleiro e peças na mesa."],["O da mão no queixo","De barba branca, pensativo."],["O do meio","Debruçado, estende a mão para uma peça."],["O da direita","Espreita por trás."],["A mão com o charuto","Um charuto entre os dedos."],["Café e fósforos","Duas chávenas, um copo e uma caixa de fósforos à esquerda."]]},"artful":{"title":"A carta astuta, ou uma a mais para a avó. Copas são trunfo!","artist":"Anónimo","date":"1852–1863","place":"Provavelmente Grã-Bretanha","game":"Cartas","medium":"Estereografia colorida","size":"8,4 × 17,4 cm","credit":"","p":["O título inglês é «The artful card, or, one too many for granny. Hearts are trumps!». Uma pequena cena cómica em que se engana a avó com uma carta astuta, feita num par de fotografias estereoscópicas. Pelo título em inglês, foi provavelmente feita na Grã-Bretanha.","Numa mesa redonda a avó e uma menina jogam às cartas, enquanto a jovem de verde, de cartas na mão, é abraçada por trás por um rapaz. «Copas são trunfo» é provavelmente um trocadilho entre o naipe e o amor. A sala com roda de fiar e aparador é certamente um cenário de estúdio."],"spots":[["As cartas da jovem","As cartas que a jovem de verde segura."],["O rapaz","Com a mão no ombro dela, por trás."],["A avó","Mulher idosa de lenço, a olhar para as cartas."],["A menina","Sorri enquanto joga uma carta."],["A mesa","Mesa redonda com cartas e pequenas coisas."],["O aparador","Um armário envidraçado com loiça."]]},"cezcards":{"title":"Estudo para Os jogadores de cartas","artist":"Paul Cézanne","date":"1890–92","place":"França","game":"Cartas","medium":"Aguarela com grafite sobre papel velino bege","size":"36,2 × 48,5 cm","credit":"","p":["Na década de 1890, em Aix, no sul de França, Cézanne pintou vários quadros de homens a jogar às cartas. Esta é uma aguarela preparatória para essa série: um homem de chapéu e bigode, sentado à mesa, olha para as suas cartas.","Sobre linhas de grafite, aguadas finas de azul e cinzento captam as pregas do casaco e o peso do corpo. O lado direito e o fundo da mesa ficam por acabar; só há cor à volta da figura. Diz-se que os modelos eram trabalhadores da terra."],"spots":[["O rosto","De olhos baixos sob o chapéu, olha as cartas."],["As cartas","Cartas seguras com as duas mãos."],["A mesa","Uma mesa desenhada só a lápis."],["A cadeira","O espaldar da cadeira, à esquerda."],["O casaco","Pregas construídas a azul e cinzento."],["O inacabado","Junto às pernas da mesa só ficam as linhas."]]},"vuillardck":{"title":"A partida de damas, de Paisagens e interiores","artist":"Édouard Vuillard","date":"1899","place":"França","game":"Damas","medium":"Litografia a cores sobre papel da China marfim-acinzentado","size":"36,9 × 28,5 cm","credit":"","p":["A primeira estampa de Paisagens e interiores, álbum de litografias a cores do pintor francês Vuillard, editado pelo marchand Ambroise Vollard e impresso pelo litógrafo Auguste Clot.","Numa sala carregada de papel de parede, um homem de barba joga diante de um tabuleiro de damas enquanto uma mulher de vestido aos quadrados, de pé, leva a mão ao queixo e observa. Figuras, papel e sofá fundem-se em cor lisa e padrão; só as casas pretas e brancas do tabuleiro sobressaem."],"spots":[["O tabuleiro","O tabuleiro de damas preto e branco."],["O homem de barba","Sentado diante do tabuleiro."],["A mulher de pé","De vestido aos quadrados e mão no queixo."],["O papel de parede","Papel cheio de linhas em remoinho."],["A almofada florida","Tecido estampado em baixo à esquerda."],["O candeeiro","Uma forma esguia de candeeiro junto à parede."]]},"cruikchess":{"title":"Partida de xadrez","artist":"George Cruikshank, segundo o capitão Frederick Marryat","date":"1814","place":"Inglaterra","game":"Xadrez","medium":"Água-forte colorida à mão","size":"23,8 × 34,5 cm","credit":"","p":["Uma estampa do caricaturista inglês Cruikshank segundo um esboço de Marryat, oficial da marinha e depois romancista, editada em Londres por Hannah Humphrey. Em baixo corre o título «GAME of CHESS».","A uma mesa com velas, dois cavalheiros idosos defrontam-se no tabuleiro. Atrás de cada um está um mirone: o da esquerda leva um dedo aos lábios pedindo silêncio, e o da direita espreita o tabuleiro por uma luneta. Provavelmente troça dos mirones que não se calam."],"spots":[["O tabuleiro","O tabuleiro com as suas peças pretas e brancas."],["As velas","Duas velas a iluminar o tabuleiro."],["O que pede silêncio","Um mirone com um dedo nos lábios."],["O da luneta","Um mirone a espreitar pela luneta."],["O cão a dormir","Um cão a dormir debaixo da mesa."],["O título","«GAME of CHESS» em baixo."]]},"domino98":{"title":"Mulher e criança a jogar dominó a uma mesa","artist":"Autor desconhecido (norte-americano)","date":"c. 1898","place":"Estados Unidos","game":"Dominó","medium":"Prova em albumina colada em vidro","size":"40,8 × 51,1 cm","credit":"","p":["Uma grande fotografia, provavelmente de um estúdio norte-americano, acabada colando-a num vidro. Uma mulher de branco e uma menina de cabelo encaracolado sentam-se de cada lado de uma mesinha com flores.","Há peças de dominó na mesa e a mulher está a colocar uma. A menina, de queixo na mão, observa. Cortinas, móvel ornamentado e quadros na parede são provavelmente um cenário de estúdio."],"spots":[["As peças","Peças brancas de dominó na mesa."],["A menina","De queixo na mão, olha as peças."],["A mulher","De branco, coloca uma peça."],["As flores","Uma jarra de flores na mesa."],["O móvel","Um móvel ornamentado ao fundo à direita."],["A inscrição","Letras brancas em baixo à direita."]]},"langkat":{"title":"Albert Glaser a jogar às cartas com dois amigos num barco, Langkat, Samatra","artist":"Anónimo (H. Ernst & Co.)","date":"1895–1905","place":"Indonésia (Langkat, Samatra)","game":"Cartas","medium":"Fotografia","size":"17,5 × 22,8 cm","credit":"","p":["Uma fotografia tirada em Langkat, no norte de Samatra. Em baixo à direita tem o carimbo seco do estúdio «H. Ernst & Co. / Bindjey Langkat», e no verso uma nota manuscrita diz que o homem do meio é Albert Glaser, irmão de uma senhora.","No convés de um barco, sob um toldo, três homens de branco sentam-se a uma mesa com cartas na mão. Na mesa há cartas e pequenas peças como moedas, e junto ao homem da direita uma garrafa. A roupa branca e o toldo falam da vida num clima quente."],"spots":[["Na mesa","Cartas distribuídas e peças como moedas."],["Glaser","O do meio abre as suas cartas; a nota do verso dá o nome."],["O da esquerda","Visto meio de costas, com cartas."],["O da direita","De bigode, cartas na mão."],["A garrafa","Uma garrafa junto ao da direita."],["O toldo","Enfeites de folhas pendurados no toldo."]]},"chatur":{"title":"Uma partida de chaturanga","artist":"Anónimo","date":"1805–1815","place":"Índia","game":"Chaturanga","medium":"Guache e ouro, pincel","size":"16,2 × 9,8 cm (imagem)","credit":"","p":["Uma miniatura indiana. Segundo o registo do museu, duas mulheres jogam chaturanga, um jogo de tabuleiro, enquanto uma criada segura um enxota-moscas. O chaturanga é um velho jogo indiano, tido como antepassado do xadrez.","Sob arcos brancos, num tapete vermelho, uma mulher de azul-escuro e outra de laranja enfrentam-se diante de um tabuleiro axadrezado. A de laranja estende a mão como se falasse. A imagem é emoldurada por uma cercadura vermelho-escura com filetes pretos e brancos."],"spots":[["O tabuleiro","Um tabuleiro axadrezado no tapete vermelho."],["A mulher de azul","Ornada de ouro, estende a mão ao tabuleiro."],["A mulher de laranja","Em frente, de mão estendida."],["A criada","De pé, atrás."],["O enxota-moscas","Erguido pela criada."],["A moldura vermelha","Uma cercadura vermelho-escura com filetes pretos e brancos."]]},"shabbarat":{"title":"Noite nos aposentos das mulheres","artist":"Anónimo","date":"1760–1770","place":"Índia","game":"Chaupar (pachisi)","medium":"Guache e ouro, pincel","size":"34,3 × 25,6 cm","credit":"","p":["Uma miniatura indiana. Segundo o registo do museu, quatro mulheres jogam um jogo de tabuleiro no amplo pátio de um palácio, o jogo chamado chaupar ou pachisi. Estão sentadas à volta de um tabuleiro de pano em forma de cruz.","A mulher à frente, à direita, segura três dados compridos, pronta a lançar. Ao lado, encostada a uma almofada, está a dama mais importante. É noite, mas há lâmpadas por todo o terraço e luzes sem conta nas muralhas distantes. O registo sugere que se celebra a festa islâmica de Shab-i-Barat."],"spots":[["O tabuleiro em cruz","O tabuleiro cruciforme estendido no chão."],["A dos dados","À frente, com os dados compridos."],["A dama da almofada","A de mais alta posição."],["A criada","Aproxima-se com uma bandeja."],["Uma lâmpada","Uma vela sob uma campânula de vidro."],["O pavilhão distante","Um jardim com fonte, um pavilhão e as luzes da cidade."]]},"govase":{"title":"Vaso ovoide com mulheres a jogar go","artist":"Anónimo (selo de «Tang Jintang»)","date":"1724","place":"China (Guangdong)","game":"Go (weiqi)","medium":"Porcelana com esmaltes sobre vidrado e dourado","size":"Altura 15,3 cm","credit":"","p":["Um vaso chinês de porcelana finíssima pintado com esmaltes. No verso, uma inscrição diz «imagem de uma partida de go, pintada no dia da Festa das Flores do ano jiachen, numa casa acolhedora junto ao rio das Pérolas, em Lingnan», com o selo vermelho «Tang Jintang». Pertenceu à coleção de porcelana do colecionador da Haia Jean Theodore Royer.","Duas mulheres enfrentam-se diante de um tabuleiro de go numa mesa; a da esquerda segura uma taça de pedras. À direita, duas mulheres e duas crianças inclinam-se para ver. No móvel atrás há antiguidades, entre elas um vaso com penas de pavão e coral."],"spots":[["O tabuleiro","Um tabuleiro de go na mesa, com pedras brancas e pretas."],["A jogadora da esquerda","Com uma taça de pedras, a apontar."],["A jogadora da direita","Debruçada sobre o tabuleiro."],["As que observam","Mulheres que espreitam por trás."],["Penas de pavão e coral","Num vaso sobre o móvel."],["A taça de pedras","Na mão da mulher da esquerda."]]},"yokihi":{"title":"Um homem joga gamão com uma dama (o imperador Xuanzong e Yang Guifei)","artist":"Anónimo (surimono)","date":"1822","place":"Japão","game":"Ban-sugoroku (gamão japonês)","medium":"Xilogravura a cores com pigmentos metálicos","size":"21,6 × 19,1 cm","credit":"","p":["Um surimono, estampa de luxo que junta imagem e poesia, impressa em papel grosso com pós metálicos e encomendada por poetas como presente para amigos. Esta tem um poema e o nome do poeta, Tachibana no Goen.","Segundo o registo do museu, o imperador Tang Xuanzong (685–762) joga sugoroku com a sua concubina favorita Yang Guifei (719–756), um jogo aparentado com o gamão e o trictrac. Num tabuleiro em forma de caixa, sobre um suporte vermelho, há peças brancas e pretas."],"spots":[["O tabuleiro","Um tabuleiro de sugoroku em caixa num suporte vermelho."],["Yang Guifei","Com flores no cabelo e a mão no tabuleiro."],["Xuanzong","De mão no queixo, olha o tabuleiro."],["O poema","Um poema e o nome do poeta em cima à esquerda."],["O biombo","Um biombo pintado com montanhas, ao fundo."],["Assinatura e selo","Uma assinatura e um selo vermelho em baixo à direita."]]},"disderi":{"title":"Homens em traje de marinheiro a jogar às cartas","artist":"Disdéri & Cie","date":"1850–1890","place":"França (Paris)","game":"Cartas","medium":"Prova em albumina (carte de visite)","size":"8,6 × 5,3 cm","credit":"","p":["Uma fotografia em formato carte de visite de um álbum, com «Disdéri & Cie, 8 Boulevard des Italiens, Paris» impresso no verso. Disdéri foi o fotógrafo que popularizou a carte de visite, pequenos retratos impressos aos muitos como cartões de visita.","Homens vestidos à antiga, de tricórnio, casaca comprida e meias brancas, jogam às cartas à volta de uma mesa decorada. O registo do museu fala de traje de marinheiro, mas provavelmente é guarda-roupa de teatro ou de mascarada. O do meio levanta-se para espreitar a mesa."],"spots":[["A mesa","Uma mesa de rebordo decorado, com cartas e copos."],["O que está de pé","De tricórnio, debruça-se sobre a mesa."],["O da esquerda","Sentado, de cartas na mão."],["O da direita","De tricórnio, com cartas na mão."],["Sapatos de fivela","Meias brancas e sapatos de fivela."],["A moldura dourada","A cercadura dourada do cartão."]]},"gans":{"title":"Jogo do ganso (espiral de 74 casas)","artist":"Jan Oortman (pai), segundo desenho de Daniel Willem Stoopendaal","date":"1763–1823","place":"Países Baixos","game":"Jogo do ganso (corrida)","medium":"Xilogravura colorida a azul, vermelho e verde","size":"40,8 × 46,8 cm","credit":"","p":["Um tabuleiro de corrida em espiral impresso nos Países Baixos. Segundo o museu, as casas vão de 1 a 74, algumas com imagens. Jan Oortman gravou a matriz segundo um desenho de Stoopendaal, cujo nome surge em baixo à direita com «invenit».","A meta, o 74, é um templo à beira-mar ao pôr do sol, no centro. Há casas com palavras como «LEER GELD» (preço da lição), «DWAALWEG» (caminho errado) e «DOMHEID / WYSHEID» (tolice / sabedoria), e um esqueleto com foice, «EINDE» (o fim); provavelmente um jogo moral sobre o caminho da vida."],"spots":[["74: o templo","A meta: um templo na margem ao pôr do sol."],["1: a partida","A primeira casa, em baixo à esquerda."],["O preço","Uma casa «LEER GELD», provavelmente onde se paga."],["O caminho errado","Um caminho na mata marcado «DWAALWEG»."],["O fim","Um esqueleto com foice: «EINDE»."],["Os dados","Uma casa com dois dados."]]},"merelle":{"title":"A merelle e o papagaio","artist":"Claudine Stella, segundo Jacques Stella","date":"1657","place":"França (Paris)","game":"Merelle (jogo do moinho)","medium":"Gravura a buril","size":"11,7 × 14,1 cm","credit":"","p":["Estampa 17 de uma série de jogos infantis gravada por Claudine Stella segundo desenhos do tio, o pintor Jacques Stella. Segundo o museu, vem de um álbum de 51 gravuras. Quem brinca são crianças nuas e gorduchas, putti.","À frente, à esquerda, jogam merelle (o moinho) num tabuleiro riscado num bloco de pedra. No chão, à direita, estão as linhas do franc du carreau, jogo de atirar moedas para os ladrilhos, e mais longe uma criança corre com um papagaio de papel. Os versos em baixo dizem que todos se esforçam por jogar bem."],"spots":[["O tabuleiro","Um tabuleiro talhado na pedra, com peças."],["O papagaio","Um papagaio de papel no alto."],["A criança do papagaio","Corre com o fio na mão."],["Franc du carreau","Quadrados e diagonais no chão."],["A criança que aponta","Com algo na mão, aponta para as linhas."],["O título","«LA MERELLE, & LE CERF VOLANT»."]]},"feldcards":{"title":"Partida de cartas numa mesa ao ar livre (estereografia)","artist":"Anónimo","date":"1850–1880","place":"Desconhecido (carimbo de uma casa de Groningen no verso)","game":"Cartas","medium":"Prova em albumina (estereografia)","size":"8,5 × 17,0 cm","credit":"","p":["Uma estereografia de uma família ou grupo de amigos a jogar às cartas na mesa de um jardim, com hera numa treliça. No verso tem o carimbo de Feldbrugge & Co., de Groningen (Países Baixos), provavelmente a loja ou o editor que a vendia.","O homem barbudo à esquerda ergue uma carta, prestes a batê-la na mesa. Um homem de cabeça apoiada na mão, um rapaz com as suas cartas, um velho de cabelo branco e uma mulher que observa por trás completam o instante. Como todos tinham de ficar imóveis, a cena foi provavelmente posada."],"spots":[["A carta erguida","A carta levantada pelo barbudo."],["Na mesa","Cartas já jogadas."],["As cartas do rapaz","As cartas do rapaz visto de costas."],["O velho","O homem de cabelo branco sentado à direita."],["A mulher que observa","De pé atrás, segue o jogo."],["A cadeira bordada","Uma cadeira à frente forrada de tecido florido."]]},"tempel":{"title":"Tabuleiro de jogo «O templo da fortuna»","artist":"Anónimo","date":"1816","place":"Países Baixos","game":"Jogo de percurso com dados","medium":"Xilogravura com texto tipográfico","size":"43,0 × 48,5 cm","credit":"","p":["Uma folha de jogo com casas de 1 a 74 em espiral. Ao centro ergue-se um templo redondo à beira-mar; a folha de regras guardada na mesma coleção chama-lhe «O templo da fortuna» e fala de um jogo de lançar, isto é, de dados.","Quase todas as casas são círculos vazios, mas aqui e ali há rosas, espinhos, dados, um portão, uma barca e outras imagens, e palavras como «LEER GELD» (propina de aprendizagem), «DOMHEID» (tolice) e «WYSHEID» (sabedoria). Provavelmente é um jogo moralizante que passa por boas e más condutas a caminho do templo."],"spots":[["O templo da fortuna","O templo à beira-mar, ao centro: a casa 74, a meta."],["A casa 1","A partida, em baixo à esquerda."],["Propina","Uma casa com «LEER GELD»."],["Os dados","Dois dados desenhados na fila de cima."],["A barca","A imagem «OVER HAAL» (travessia) na fila de baixo."],["Tolice e sabedoria","As palavras «DOMHEID» e «WYSHEID» à direita."]]},"verkeer":{"title":"Tabuleiro em miniatura de verkeer","artist":"Anónimo","date":"1690–1710","place":"Países Baixos (Amesterdão)","game":"Verkeer (parente do gamão), xadrez, moinho","medium":"Nogueira embutida com oliveira, ébano, buxo e osso; ferragens de cobre","size":"Fechado 5,8 × 5,8 cm (aberto 11,6 cm)","credit":"","p":["Um tabuleiro de jogo com apenas seis centímetros de lado que se abre como uma caixa. Por fora tem um tabuleiro de xadrez e outro de moinho; por dentro, um de verkeer, parente holandês do gamão. Fecha com dobradiças de cobre e um ganchinho.","Lá dentro restam um dado, nove peças de osso, quatro de ébano e três moedinhas. O número de inventário indica que provavelmente pertence ao recheio da casa de bonecas de Petronella Oortman. Apesar de minúsculo, o embutido é cuidadoso e é feito como um tabuleiro verdadeiro."],"spots":[["O dado","Um dado do tamanho de um grão de arroz."],["As peças de osso","Peças redondas de osso branco."],["As peças de ébano","Peças pretas de ébano."],["As casas","Triângulos embutidos em madeira clara e escura."],["As dobradiças","Dobradiças de cobre para o dobrar."],["O gancho","Um ganchinho de cobre para o fechar."]]},"silverbd":{"title":"Tabuleiro de prata em miniatura com peças","artist":"Frederik van Strant II","date":"1739","place":"Países Baixos (Amesterdão)","game":"Damas, moinho","medium":"Prata","size":"5,4 × 5,4 cm","credit":"","p":["Um tabuleiro de prata com apenas 5,4 centímetros de lado: 64 casas, um rebordo levantado e uma argola para pendurar. As casas escuras estão gravadas com linhas finas, e o outro lado tem gravadas as linhas do moinho.","Tem a marca da cidade de Amesterdão, a letra de data E de 1739 e a marca do ourives Frederik van Strant II. Com ele conservam-se quinze peças de damas, oito com uma flor e sete com um círculo. Seria provavelmente uma miniatura de prata para uma casa de bonecas ou uma vitrina."],"spots":[["Peças com flor","Peças estampadas com uma flor."],["Peças com círculo","Peças marcadas com um círculo."],["A argola","Uma argola no canto do tabuleiro."],["Casas gravadas","Casas escuras com linhas finas."],["Casas lisas","Casas claras, lisas e polidas."],["O rebordo","O bordo levantado à volta."]]},"schaak1550":{"title":"Jogo de xadrez com peças a cavalo","artist":"Anónimo","date":"1550","place":"Alemanha","game":"Xadrez","medium":"Buxo e madeira de conífera","size":"Peça maior 10,5 cm de altura","credit":"","p":["Cada peça ergue-se sobre um pé torneado rodeado de uma grade de florões, com cavaleiros e cavalos esculpidos. Reis e rainhas montam cavalos ou mulas, como se partissem para a caça.","Segundo o registo do museu, o rei preto monta um cavalo empinado que pisa um dragão e usa ao pescoço uma cadeia que lembra a Ordem do Tosão de Ouro, talvez para o identificar como Carlos V. Uma rainha monta de lado uma mula, com um falcão na mão. À direita, uma peça cómica mostra um macaco às costas de um homem."],"spots":[["O rei","Um rei coroado e barbudo, a cavalo."],["A rainha","Uma rainha de lado numa mula, com um falcão."],["A peça do macaco","Um macaco às costas de um homem."],["Uma peça cómica","À esquerda, um homem às costas de outro."],["As criaturas","Dragões e bichos debaixo dos cascos."],["Os pés","Pés torneados com florões."]]},"kraaij":{"title":"Homens e mulheres a jogar um jogo de tabuleiro numa sala","artist":"Anónimo","date":"1900–1910","place":"Provavelmente Países Baixos","game":"Gamão","medium":"Prova em colódio de enegrecimento direto","size":"8,0 × 11,1 cm","credit":"","p":["Uma página de um álbum de família que também tem fotografias dos comerciantes de vinho Kraaij & Co., Bordéus–Amesterdão. Numa sala com lustre, homens e mulheres, talvez família e amigos, sentam-se à mesa.","Na mesa está aberto um tabuleiro em forma de caixa dobrável, e as mulheres de cada lado seguram um copo de dados. O registo do museu diz «um jogo de tabuleiro», mas pela caixa e pelos copos é provavelmente gamão. Há chávenas de café por perto e uma gaiola ao fundo: um serão tranquilo em casa."],"spots":[["O tabuleiro-caixa","Uma caixa dobrável aberta como tabuleiro."],["O copo da esquerda","O da mulher de óculos."],["O copo da direita","A mulher do vestido às bolinhas prestes a lançar."],["A gaiola","Uma gaiola num suporte, ao fundo."],["O lustre","Candeeiros com globos de vidro pendurados."],["O homem de pé","À direita, a olhar o jogo."]]},"braekel":{"title":"Um velho e uma velha a jogar damas","artist":"Ferdinand De Braekeleer (I)","date":"1862","place":"Bélgica (Antuérpia)","game":"Damas","medium":"Água-forte","size":"21,8 × 16,5 cm","credit":"","p":["Uma água-forte do pintor de Antuérpia De Braekeleer (1792–1883), assinada em baixo à esquerda «Ferdinand De Braekeleer Antwerpen 1862». Numa velha cozinha com lareira, um velho e uma velha sentam-se a uma mesinha.","Há peças redondas no tabuleiro; ele pega numa e ela abre a mão como se respondesse. No chão está um chapéu e caíram também algumas peças. Na prateleira há pratos, e pela janela veem-se casas."],"spots":[["Tabuleiro e peças","O tabuleiro e as peças redondas na mesa."],["O velho","Debruçado, pega numa peça."],["A velha","De capuz, gesticula ao falar."],["O chapéu","O chapéu do velho no chão."],["A assinatura","«Ferdinand De Braekeleer Antwerpen 1862»."],["Os pratos","Grandes pratos na prateleira sobre a lareira."]]},"billiard":{"title":"Bilhar","artist":"Segundo H. W. Bunbury (gravador anónimo)","date":"1780","place":"Inglaterra (Londres)","game":"Bilhar","medium":"Água-forte e pontilhado","size":"30,0 × 39,1 cm","credit":"","p":["Uma gravura segundo o caricaturista inglês Henry William Bunbury, publicada em Londres em 1780 por Watson & Dickinson. Segundo o museu, é a número quatro de uma série.","Dois homens jogam bilhar enquanto os outros observam, sustendo a respiração. Um debruça-se sobre a mesa para jogar; outro leva o taco ao ombro. Na parede há um porta-tacos e dois mostradores redondos de pontuação. O museu nota que a mesa parece triangular."],"spots":[["Mesa e bolas","A mesa com pano e as suas bolas."],["O que aponta","Debruçado sobre a mesa para jogar."],["O do taco","Espera com o seu longo taco."],["Os mostradores","Dois mostradores na parede, provavelmente para contar pontos."],["O porta-tacos","Uma fila de tacos contra a parede."],["Os dois que riem","Dois mirones à direita, a rir juntos."]]},"baizi":{"title":"Cem crianças (pormenor)","artist":"Xu Yanghong","date":"Século XVIII","place":"China","game":"Weiqi (go)","medium":"Rolo horizontal; tinta (e cor ligeira) sobre papel","size":"29,8 × 526 cm (rolo inteiro)","credit":"","p":["Uma cena de go recortada de um rolo com mais de cinco metros do pintor profissional chinês Xu Yanghong. Num jardim, cem crianças brincam, fazem música, leem e escrevem. As «cem crianças» são um tema importante da arte asiática, símbolo de fertilidade e prosperidade familiar.","O rolo é também conhecido por uma cópia posterior do mestre japonês Tani Bunchō, no mesmo museu. Junto a folhas de bananeira e a uma pedra de letrado, as crianças rodeiam um tabuleiro de go num suporte baixo; duas jogam de taça de pedras na mão e as outras espreitam."],"spots":[["O tabuleiro","Um tabuleiro de go num suporte baixo, com pedras."],["A criança que joga","De casaco azul, a mão na taça de pedras."],["O outro jogador","De branco, debruçado sobre o tabuleiro."],["Mãos atrás da cabeça","Uma criança que observa por trás."],["A pedra de letrado","Uma grande rocha cheia de buracos."],["O leque de penas","Uma criança à esquerda com um leque de penas."]]},"schenkcards":{"title":"Duas mulheres chinesas a jogar às cartas","artist":"Pieter Schenk (II)","date":"1727–1775","place":"Países Baixos (tema: China)","game":"Cartas","medium":"Água-forte","size":"16,5 × 26,2 cm","credit":"","p":["Uma estampa da primeira parte de «Chineses recém-inventados», álbum de figuras e paisagens de estilo chinês publicado pelo gravador e editor de Amesterdão Pieter Schenk, o Jovem. É uma chinoiserie, o gosto por uma China imaginada que esteve na moda na Europa.","Segundo o registo do museu, duas mulheres chinesas jogam às cartas num jardim enquanto outra chega pela direita com um tabuleiro cheio. As cartas na mesa parecem europeias. À esquerda um coelho descansa num suporte, e no rio há um veleiro."],"spots":[["As cartas","Cartas espalhadas na mesa; parecem europeias."],["A mulher da esquerda","De cartas na mão, olha a parceira."],["A mulher da direita","Pousa uma carta na mesa."],["A mulher do tabuleiro","Traz um tabuleiro cheio de comida."],["O coelho","Descansa num suporte à esquerda."],["O veleiro","Um barco no rio."]]},"gosaucer":{"title":"Pires com figuras a jogar go","artist":"Anónimo","date":"1725–1735","place":"China","game":"Go (weiqi)","medium":"Porcelana com esmaltes sobre vidrado e dourado","size":"Diâmetro 16,4 cm","credit":"","p":["Um pires chinês pintado nas suaves cores sobre vidrado chamadas família rosa. Por baixo tem uma marca de um pincel, um cetro ruyi e um pau de tinta num duplo círculo. Os registos do museu descrevem as figuras ora como um homem e uma mulher a jogar go, ora como três mulheres, duas das quais jogam.","Numa sala há um tabuleiro de go numa mesa; dois jogadores, frente a frente, colocam pedras, e um terceiro observa de pé atrás. Na mesa há taças amarelas para as pedras; atrás, um suporte com um vaso de flores, e à direita um grande pote azul."],"spots":[["O tabuleiro","Um tabuleiro de go com pedras na mesa."],["O jogador da esquerda","De lilás claro, encostado à mesa."],["O jogador da direita","De cor-de-rosa, a colocar uma pedra."],["O que observa","De pé atrás, a ver."],["O vaso","Um vaso de flores num suporte."],["O pote azul","Um grande pote à direita."]]},"cheetham":{"title":"Uma pequena partida de cartas (na Rússia)","artist":"Anónimo","date":"1903–1904","place":"Rússia","game":"Cartas","medium":"Prova em gelatina de enegrecimento direto","size":"9,2 × 11,5 cm","credit":"","p":["Do álbum da família inglesa Cheetham, que viveu na Rússia; no cartão lê-se em inglês «a little card-party». O museu indica que são provavelmente amigos ingleses de visita a Joseph Cheetham.","Numa sala com papel de parede, três pessoas sentam-se a uma mesa com toalha florida, de cartas abertas. Há dois castiçais na mesa, e a mulher do meio ri ao abrir a sua mão. Foi provavelmente um momento descontraído com amigos da terra, num país distante."],"spots":[["As cartas do da esquerda","A mão do homem barbudo."],["As cartas da mulher","A mulher do meio abre as cartas em leque."],["O da direita","Inclinado, de cartas na mão."],["Os castiçais","Dois castiçais na mesa."],["A toalha","Uma grande toalha com flores e motivos."],["A inscrição","«a little card-party» no cartão."]]},"problem":{"title":"O problema (estereografia)","artist":"Anónimo","date":"1852–1863","place":"Desconhecido","game":"Xadrez","medium":"Estereografia colorida","size":"8,4 × 17,4 cm","credit":"","p":["O título inglês é «The Problem». Duas figuras de cabeleira branca e trajes de estilo setecentista jogam xadrez a uma mesa ornamentada, num par colorido de fotografias estereoscópicas. No verso está escrito à mão «Simons».","O mais novo segura as faces com as duas mãos e fita o tabuleiro, enquanto o mais velho à frente sorri maliciosamente. É provavelmente uma cena teatral encenada, em que se vê logo quem tem o problema. Um cão está deitado aos seus pés."],"spots":[["Tabuleiro e peças","O tabuleiro e as peças na mesa ornamentada."],["O jogador aflito","De cabeça entre as mãos, fita o tabuleiro."],["O que sorri","O mais velho de casaca azul, a sorrir."],["O cão","Um cão deitado aos seus pés."],["A cortina vermelha","A cortina colorida ao fundo."],["A segunda imagem","A vista da direita; no estereoscópio ganha profundidade."]]},"tarocco":{"title":"Dez cartas de um baralho de tarot","artist":"Anónimo (provavelmente segundo Giuseppe Maria Mitelli)","date":"1660–1718","place":"Itália (Bolonha)","game":"Tarocchi (jogos de cartas com trunfos)","medium":"Água-forte e buril, em parte coloridos à mão a castanho-claro","size":"Dez cartas num suporte","credit":"","p":["Dez cartas de um baralho de tarot bolonhês, coladas lado a lado num suporte. O tarot não serviu primeiro para adivinhar, mas para jogos de cartas com trunfos. Em cima à esquerda há uma carta de título; o museu sugere que o retrato pode ser do artista Mitelli.","A fila de cima mostra quatro figuras, entre elas um homem coroado e um cavaleiro; a de baixo, do seis ao dez do naipe de ouros, cada carta com tantas moedas quanto o número. As linhas impressas têm em parte uma aguada castanho-clara."],"spots":[["A carta de título","Em cima à esquerda: um retrato emoldurado e uma inscrição."],["O homem coroado","Uma figura coroada com ceptro."],["A mulher de pé","Uma mulher coroada com uma taça."],["O cavaleiro","Uma carta com uma figura a cavalo."],["Dez de ouros","Em baixo à esquerda: dez moedas."],["Seis de ouros","Em baixo à direita: seis moedas."]]},"kindtegel":{"title":"Azulejos com cenas de crianças a brincar","artist":"Anónimo","date":"1680–1730","place":"Países Baixos","game":"Brincadeiras infantis (andas, baloiço e mais)","medium":"Faiança (azulejos de Delft), pintada a azul","size":"107 × 80 cm (48 azulejos)","credit":"","p":["Um painel de quarenta e oito azulejos, oito de altura por seis de largura. Cada um mostra duas crianças a brincar, pintadas em pequeno a azul, com um ornamento chamado «aranha» em cada canto.","Uma anda em andas, outra é empurrada num baloiço, outras agacham-se sobre algo no chão: cada azulejo mostra uma brincadeira diferente. Estes azulejos de «brincadeiras de crianças» eram apreciados nos Países Baixos e provavelmente revestiam paredes de cozinhas e a volta das lareiras."],"spots":[["As andas","Uma criança em andas."],["O baloiço","Uma criança empurrada num baloiço."],["Uma brincadeira no chão","Crianças agachadas a brincar com algo no chão."],["As aranhas","Os pequenos ornamentos dos cantos."],["Quarenta e oito azulejos","Oito filas de seis azulejos."],["O último azulejo","O azulejo do canto inferior direito."]]},"dammolen":{"title":"Tabuleiro em miniatura de damas e moinho","artist":"Anónimo","date":"1740–1760","place":"Países Baixos (Amesterdão)","game":"Damas, moinho","medium":"Nogueira com pasta de enchimento clara","size":"4,2 × 4,0 × 1,5 cm","credit":"","p":["Um tabuleirinho de nogueira com cerca de quatro centímetros. Quase quadrado e com rebordo, serve de um lado para damas e do outro para o jogo do moinho.","Na face das damas, as casas foram escavadas e cheias com uma pasta clara, formando o xadrez sobre a madeira; na do moinho, as linhas gravadas foram cheias com a mesma pasta. Tão pequeno, foi provavelmente feito para uma casa de bonecas."],"spots":[["Casas cheias","Casas escavadas e cheias de pasta clara."],["Casas de madeira","Casas em nogueira à vista."],["O rebordo","O bordo levantado à volta."],["O canto próximo","O canto mais próximo."],["A espessura","O lado do tabuleiro, com 1,5 cm."],["A fila do fundo","A fila de casas do fundo."]]},"karelpiece":{"title":"Peça de damas com retrato de Carlos Magno (metade)","artist":"Anónimo","date":"1525–1575","place":"Alemanha (Nuremberga)","game":"Damas ou tábulas","medium":"Buxo","size":"Diâmetro 5,3 cm","credit":"","p":["Uma face de uma peça de damas esculpida em buxo. Ao centro, um perfil dentro de uma coroa de louros; à volta, a inscrição «CAROLVS. MAGNVS. IMPER. AVGVST.» (Carlos Magno, imperador).","O museu guarda mais de uma dúzia de peças do mesmo tipo, cada uma com um imperador ou imperatriz da Roma antiga à Idade Média: Tibério, Agripina, Luís o Piedoso, Otão e outros. Seria provavelmente um jogo de luxo pensado como uma galeria de soberanos."],"spots":[["O perfil","O perfil de Carlos Magno numa coroa de louros."],["A coroa","O anel de louros à volta do retrato."],["CAROLVS","As palavras «CAROLVS. MAGNVS» em cima."],["AVGVST","As palavras «IMPER. AVGVST» à esquerda."],["A estrela","Uma estrelinha a separar a inscrição."],["O bordo","O bordo escalonado da peça."]]},"vdberge":{"title":"O jogo holandês, a boa vida! (Cartas)","artist":"Pieter van den Berge (desenho e edição)","date":"1694–1737","place":"Países Baixos (Amesterdão)","game":"Cartas","medium":"Água-forte impressa à la poupée a vermelho, azul e verde","size":"27,3 × 17,0 cm","credit":"","p":["Uma sátira do gravador e editor de Amesterdão Van den Berge, intitulada «LE JEU HOLLANDOIS. LA BELLE VIE!». Segundo o museu, homens jogam às cartas numa taberna enquanto diabos, junto a um homem que suspira de copo erguido e debaixo da mesa, lhe ganham o dinheiro.","No verso neerlandês em baixo, o boémio despreocupado lamenta que lutas de cães e de galos, cartas e dados lhe derreteram o dinheiro. De cada lado, dois diabos tentam-no em alemão a divertir-se com dados e cartas. O quadro ao fundo mostra também lutas de cães e de galos."],"spots":[["O homem do copo","O boémio de grande peruca, de copo erguido."],["As cartas","Cartas abertas na mão do homem."],["O diabo da esquerda","Um diabo a sorrir atrás dele."],["O diabo sob a mesa","Apanha as moedas caídas no chão."],["O quadro das lutas","Uma pintura de lutas de cães e galos."],["Título e verso","«LE JEU HOLLANDOIS» e o lamento do boémio."]]},"crespi":{"title":"Crianças a jogar aos dados","artist":"Giuseppe Maria Crespi","date":"1675–1747","place":"Itália","game":"Dados","medium":"Água-forte","size":"22,5 × 15,1 cm","credit":"","p":["Uma água-forte do pintor bolonhês Crespi, gravada pela sua mão. Segundo o museu, quatro crianças jogam aos dados na rua, e por baixo há um verso italiano de três linhas.","Uma criança agachada acabou de lançar os dados no chão enquanto as outras três observam. O verso fala de ossos (dados) e números, de um jogo breve e de dinheiro que diminui; provavelmente acrescenta um aviso contra o jogo mesmo a uma brincadeira infantil."],"spots":[["Os dados","Pequenos dados no chão."],["A criança agachada","Acabou de lançar os dados."],["A criança de pé","Espreita o lançamento."],["A criança da direita","Sentada no chão, observa."],["A criança de trás","Espreita por detrás das outras."],["O verso","Três linhas de verso italiano."]]},"epinal":{"title":"O grande jogo do ganso (Épinal)","artist":"Pellerin & Cie (Épinal)","date":"1791–1900","place":"França (Épinal)","game":"Jogo do ganso (corrida)","medium":"Xilogravura colorida a amarelo, vermelho, verde e azul; texto tipográfico","size":"39,8 × 59,0 cm","credit":"","p":["Uma folha a cores da imprensa Pellerin de Épinal, no leste de França, com o título francês «GRAND JEU DE L’OIE». Segundo o museu, uma espiral de 63 casas mostra gansos, outros animais e figuras, com o título neerlandês «GANZENBORD!» e as regras impressas ao centro.","Segundo as regras, lançam-se dois dados, e cair num ganso permite avançar outro tanto. A ponte do 6 leva ao 12, a estalagem do 19 custa duas vezes, no poço (31) espera-se que chegue outro, o labirinto (42) manda de volta ao 30 e a morte (58) ao início. É preciso chegar ao 63 exato para ganhar. Dos dois lados há fichas para recortar."],"spots":[["63: o ganso","A meta, o 63: um ganso num lago."],["As regras","As regras neerlandesas ao centro."],["Fichas para recortar","Fichas redondas numeradas dos dois lados."],["O título","«GRAND JEU DE L’OIE» no topo."],["Crianças a brincar","Crianças no canto inferior esquerdo."],["O editor","«PELLERIN & Cie» em cima à esquerda."]]},"matham":{"title":"Casal a jogar trictrac","artist":"Jacob Matham (editor), versos de Simon Sovius","date":"1621","place":"Países Baixos (Haarlem)","game":"Trictrac (parente do gamão)","medium":"Gravura a buril","size":"17,9 × 20,0 cm","credit":"","p":["A terceira estampa de uma série de quatro publicada pelo gravador e editor de Haarlem Matham. Segundo o museu, um casal elegante joga trictrac a dinheiro numa mesinha; a bolsa está na mesa e a senhora segura os dados.","As longas casas e as peças claras e escuras do tabuleiro estão gravadas com nitidez. Por baixo há versos em latim e neerlandês; o neerlandês avisa que não é só o excesso de bebida que desperta pensamentos impuros, mas que o jogo e os dados vão contra todo o proveito. Atrás, um rapaz ergue um copo de vinho."],"spots":[["O tabuleiro","Um tabuleiro de trictrac com casas e peças."],["O homem que joga","O do chapéu estende a mão sobre o tabuleiro."],["A senhora dos dados","De grande gola, segura os dados."],["O rapaz do copo","Ergue um copo de vinho atrás."],["A bolsa","A bolsa das apostas na mesa."],["Os versos","Versos de aviso em latim e neerlandês."]]},"jardin":{"title":"Três homens a jogar às cartas numa mesa de jardim, com um espectador (França)","artist":"Anónimo (um fotógrafo amador francês)","date":"1900–1910","place":"França","game":"Cartas","medium":"Prova em albumina","size":"11,8 × 17,2 cm","credit":"","p":["Do álbum de um fotógrafo amador francês, que também tem fotografias de uma família, da destilaria Delizy & Doistau, do exército e de lugares de interesse de França.","À sombra de um jardim de gravilha, três homens jogam às cartas numa mesinha enquanto um velho de barba branca observa de pé atrás. Há cartas na mesa e o do chapéu de palha estuda a sua mão. Foi provavelmente um momento descontraído entre família ou amigos."],"spots":[["Cartas na mesa","Cartas jogadas na mesa."],["O espectador","O velho de barba branca, de pé atrás."],["O do chapéu de palha","Ao meio, a estudar a mão."],["O da direita","De casaco escuro, com cartas."],["O da esquerda","De casaco claro."],["O jardim","A gravilha e os arbustos do jardim."]]},"lamplight":{"title":"Pessoas a jogar às cartas (sob o candeeiro)","artist":"Anónimo","date":"1900–1910","place":"Desconhecido","game":"Cartas","medium":"Prova em gelatina e prata","size":"7,5 × 10,0 cm","credit":"","p":["Uma pequena fotografia de um álbum, intitulada pelo museu «Pessoas a jogar às cartas». Não se conhecem o fotógrafo nem o lugar.","À luz de um candeeiro de petróleo pendurado do teto, uma mulher de vestido às riscas, uma menina e alguns rapazes sentam-se a uma mesa com toalha de franjas, de cartas abertas em leque. Fotografar numa sala escura devia ser difícil; provavelmente quis-se captar um serão de família."],"spots":[["A toalha de franjas","Uma toalha estampada com franjas."],["O candeeiro","Um candeeiro de petróleo pendurado."],["A mulher às riscas","Sentada com vestido branco às riscas."],["As cartas da mulher","As cartas que segura em leque."],["As cartas da menina","A menina do meio abre a mão."],["O rapaz da direita","Inclinado, com cartas."]]},"borduur":{"title":"Tampo bordado de mesa de jogo com uma partida de cartas","artist":"Anónimo","date":"1700–1725","place":"Desconhecido","game":"Cartas","medium":"Ponto grosso e petit point em lã e seda de cores","size":"100 × 185 cm","credit":"","p":["Bordado do tampo de uma mesa de jogo dobrável, em lã e seda de muitas cores, combinando ponto grosso e petit point. Dentro de uma forma de cantos cortados corre uma moldura de volutas e flores.","Na paisagem central, duas senhoras e um cavalheiro jogam às cartas à volta de uma mesa. Segundo o registo do museu, sobre a mesa há uma bolsa, cartas e outros apetrechos de jogo. Uma mesa de jogo decorada, a propósito, com uma partida de cartas."],"spots":[["A mesa","A mesa verde com a bolsa e as cartas."],["O cavalheiro","Um homem de chapéu, sentado à esquerda."],["A senhora ao centro","Uma senhora sentada atrás da mesa."],["A senhora à direita","Uma senhora vestida de azul."],["As árvores","Árvores atrás das figuras."],["A moldura","Uma moldura de volutas e flores."]]},"piquet":{"title":"Pano estampado com um jogo de piquet","artist":"Anónimo","date":"1725–1750","place":"Desconhecido","game":"Piquet (jogo de cartas)","medium":"Linho estampado a vermelho e roxo","size":"73,0 × 82,5 cm","credit":"","p":["Um pano de linho para mesa de jogo, todo estampado a vermelho e roxo com os apetrechos de um jogo de cartas. O registo do museu descreve-o também como lenço.","Cartas de piquet — jogado com 32 cartas do sete ao ás — espalham-se pela cercadura e pelo centro, com uma bolsa no meio e fichas à volta. As figuras são do padrão de Paris, com nomes como César, Argine e Hogier."],"spots":[["A bolsa","A bolsa das apostas, ao centro."],["As figuras","Reis e damas do padrão de Paris."],["As fichas","Fichas redondas."],["A cercadura de cartas","Uma faixa de cartas à volta do pano."],["Maços voltados","Maços que mostram o verso."],["O pacote selado","Um pacote de cartas selado, em baixo à direita."]]},"schaakglas":{"title":"Copo gravado com dois homens a jogar xadrez","artist":"Anónimo","date":"1815–1830","place":"Desconhecido","game":"Xadrez","medium":"Vidro incolor transparente, gravado à roda","size":"Alt. 13,7 cm","credit":"","p":["Um copo de vidro transparente com pé, com imagem e letras gravadas com uma pequena roda giratória. A uma mesinha com duas velas, dois homens defrontam-se num tabuleiro de xadrez.","O da esquerda, de óculos, fuma cachimbo; o da direita debruça-se sobre o tabuleiro, e há um copo de vinho na mesa. À volta corre uma inscrição em francês: saber as jogadas é coisa simples; saber o jogo é fruto do génio."],"spots":[["O tabuleiro","O tabuleiro com as suas peças."],["O do cachimbo","À esquerda, de óculos e cachimbo."],["O que se debruça","À direita, a olhar o tabuleiro."],["As velas","Duas velas atrás do tabuleiro."],["O copo de vinho","Um copo na mesa."],["A inscrição","Palavras gravadas em francês."]]},"arlequin":{"title":"O jogo de loto de Arlequim","artist":"Anónimo (editado por Mindermann & Co.)","date":"1818–1845","place":"Países Baixos (Amesterdão)","game":"Loto / jogo de percurso","medium":"Gravura colorida à mão, colada em cartão","size":"Desconhecido","credit":"","p":["Uma folha de jogo cujo tabuleiro é a própria figura de Arlequim, de pé com as pernas afastadas. Casas quadradas numeradas de 1 a 32 percorrem o seu traje verde e o espaço entre as pernas. Em baixo estão o título «Arlequin’s Lotto-Spel» e o nome de Mindermann & Co., de Amesterdão.","Usa uma máscara de rede e segura um chapéu e algo parecido com uma espada de madeira. Algumas casas têm «HW» ou «P». A gravura colorida foi colada em cartão, provavelmente para servir de tabuleiro."],"spots":[["A máscara de rede","A rede que lhe cobre o rosto."],["A casa 1","A partida, debaixo da perna esquerda."],["Uma casa HW","Uma casa marcada «HW»."],["P 32","A casa 32, marcada «P»."],["O título","«Arlequin’s Lotto-Spel» em baixo."],["O chapéu","O chapéu na mão direita."]]},"vicaire":{"title":"A partida do vigário","artist":"René Gayant (segundo a estampa)","date":"1888–1893","place":"França","game":"Cartas","medium":"Fototipia (segundo o museu)","size":"10,4 × 15,6 cm","credit":"","p":["Uma estampa do Bulletin du Photo-Club de Paris, intitulada «La partie du Vicaire» (a partida do vigário). A margem tem impresso «Phototype René Gayant» e «Héliogravure Lemercier», pelo que a fotografia será de Gayant e a impressão de Lemercier. Estava encadernada de lado no livro.","Numa cozinha com tachos e frigideiras pendurados, um padre de batina preta, sentado à mesa, estuda as suas cartas, e o homem em frente também tem cartas. Um homem de boné apoia o queixo na mão e um jovem, de mão na orelha, segue o jogo. A luz e a composição de quadro condizem com um clube dedicado à fotografia artística."],"spots":[["As cartas do padre","As cartas que o padre estuda."],["O padre","De batina preta e colarinho branco."],["O homem com cartas","De cabelo encaracolado, olha a mão."],["O jovem que observa","De mão na face, segue o jogo."],["O homem de boné","De queixo apoiado na mão."],["A parede da cozinha","Tachos e conchas pendurados."]]}};
